-- ============================================================================
-- アイスブレイク(66件)と学級レク(60件)を、
-- 管理画面(/admin/activities)から編集できるようにする
--
-- つながらないときは icebreakers.ts / recreations.ts の内容にもどるので、
-- 表示が消えることはありません。
--
-- 行数が多いので、Supabase の SQL Editor に貼り付けて実行するのに少し時間がかかります。
-- 何度実行しても安全です。
-- ============================================================================

create table if not exists icebreakers (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  title text not null,
  emoji text not null default '',
  scene text not null default 'circle',
  category text not null,
  duration text not null default '',
  place text not null default '',
  group_size text not null default '',
  materials text not null default '',
  steps text[] not null default '{}',
  tip text,
  variation text,
  sort_order integer not null default 0,
  hidden boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists recreations (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  title text not null,
  emoji text not null default '',
  scene text not null default 'tag',
  category text not null,
  grades text[] not null default '{}',
  occasions text[] not null default '{}',
  duration text not null default '',
  prep text not null default '',
  place text not null default '',
  places text[] not null default '{}',
  group_size text not null default '',
  materials text not null default '',
  steps text[] not null default '{}',
  tip text,
  variation text,
  safety text,
  inclusion text,
  icebreaker_slug text,
  sort_order integer not null default 0,
  hidden boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table icebreakers enable row level security;
drop policy if exists "icebreakers are publicly readable" on icebreakers;
create policy "icebreakers are publicly readable" on icebreakers for select using (not hidden);
drop policy if exists "admins can read all icebreakers" on icebreakers;
create policy "admins can read all icebreakers" on icebreakers for select using (is_admin());
drop policy if exists "admins can insert icebreakers" on icebreakers;
create policy "admins can insert icebreakers" on icebreakers for insert with check (is_admin());
drop policy if exists "admins can update icebreakers" on icebreakers;
create policy "admins can update icebreakers" on icebreakers for update using (is_admin()) with check (is_admin());
drop policy if exists "admins can delete icebreakers" on icebreakers;
create policy "admins can delete icebreakers" on icebreakers for delete using (is_admin());

alter table recreations enable row level security;
drop policy if exists "recreations are publicly readable" on recreations;
create policy "recreations are publicly readable" on recreations for select using (not hidden);
drop policy if exists "admins can read all recreations" on recreations;
create policy "admins can read all recreations" on recreations for select using (is_admin());
drop policy if exists "admins can insert recreations" on recreations;
create policy "admins can insert recreations" on recreations for insert with check (is_admin());
drop policy if exists "admins can update recreations" on recreations;
create policy "admins can update recreations" on recreations for update using (is_admin()) with check (is_admin());
drop policy if exists "admins can delete recreations" on recreations;
create policy "admins can delete recreations" on recreations for delete using (is_admin());

insert into icebreakers (slug, title, emoji, scene, category, duration, place, group_size, materials, steps, tip, variation, sort_order)
select * from (values
  ('catch', 'キャッチ', '👆', 'circle', '体を動かす系', '5〜10分', '教室（机は不要）', 'クラス全体', 'なし', array['全員で輪になって立つ（または座る）。', '左手のひらを上に向けて「お皿」の形を作り、右手の人差し指を隣の人の左手の上にそっと立てる。', '先生が「キャッチ」と声をかけたら、右手はサッと引いて逃げ、左手はすばやく握って隣の人の指を捕まえる。', '捕まえられた人・逃げ切った人がそれぞれ分かるので、盛り上がったところで終了。']::text[], '「キャ……メラ」のように似た言葉で引っかけると、さらに盛り上がります。', '「キャ」で始まる言葉をいくつも用意しておくと、緊張感が続いて飽きません。', 1),
  ('hidden-common-point', '隠れた共通点', '🔍', 'small-group', '会話・自己紹介系', '10〜15分', '教室', '3〜4人グループ', '紙とペン（ミニホワイトボードがあれば尚可）', array['3〜4人のグループを作る。', '制限時間内に、グループ全員に共通することを話し合って探す（例：好きな食べ物、好きな教科、行ったことがある場所など）。', '見つけた共通点を紙に書き出す。時間内にいくつ見つけられたか、グループごとに発表する。']::text[], '「見た目でわからないもの」に絞ると、会話が生まれやすくなります。', null, 2),
  ('janken-champion', 'ジャンケンチャンピオン', '✊', 'front', '体を動かす系', '1〜3分', '教室', 'クラス全体', 'なし', array['先生 対 クラス全員でジャンケンをする。', '先生に負けた人はその場に座る。勝った人・あいこの人は立ったまま次のジャンケンへ。', '最後まで立って残った人が「チャンピオン」。数回で決着がつく、とても短時間の活動。']::text[], '隙間時間にぴったり。チャンピオンに一言コメントしてもらうとさらに盛り上がります。', null, 3),
  ('safe-fruits-basket', '安心なんでもバスケット', '🪑', 'seated-circle', '体を動かす系', '10〜15分', '教室', 'クラス全体', '人数分の椅子（本人の椅子を含めて全員分）', array['椅子を円形に、人数分（先生の分は無し）並べて座る。', '「〇〇な人」（例：犬を飼っている人、朝ごはんを食べてきた人）とお題を出す。', '当てはまる人は立って、自分以外の空いた椅子に移動する。移動できなかった場合も、責められない・順位をつけない雰囲気を大切にする。', '何度かお題を変えて繰り返す。']::text[], '通常のフルーツバスケットと違い「負けても何も起きない」ルールにすることで、苦手な子も安心して参加できます。', null, 4),
  ('beat-five', 'ビート５', '🙌', 'pair', '体を動かす系', '5分程度', '教室', 'ペア〜クラス全体', 'なし', array['2人1組になって向かい合う。', 'せーので手を合わせようとする（相手が出す手のタイミング・高さを予想して合わせる）。', '1回でぴったり手が合ったら成功。慣れてきたら3人、4人とグループの人数を増やして挑戦する。']::text[], '声を出さずに息を合わせる遊びなので、静かめのクラスでも取り組みやすいです。', null, 5),
  ('common-point-pair', '共通点探しゲーム', '🤝', 'pair', '会話・自己紹介系', '5分', '教室（机は不要）', '2〜3人組', 'なし', array['2〜3人のペア・グループを作る。', '制限時間1分で、お互いの共通点を3つ見つける（好きな食べ物、好きな教科など）。', '毎回ペアを変えて2〜3回繰り返す。']::text[], 'クラス替え直後の学級開きにも使いやすい、会話のきっかけ作りゲームです。', null, 6),
  ('delayed-janken', '後出しじゃんけん', '✌️', 'front', '体を動かす系', '3〜5分', '教室', 'クラス全体', 'なし', array['先生が「じゃんけん、ぽん」で先に手を出す。', '子どもたちは少し遅れて、「先生に勝つ手」を出す。', '慣れてきたら「先生に負ける手」「あいこになる手」に変えると、とっさに考える必要が出て盛り上がる。']::text[], '立ったまま全員参加できるので、授業と授業の間の切り替えにも向いています。', null, 7),
  ('one-minute-speech', '1分間スピーチのお題引き', '🎤', 'pair', '会話・自己紹介系', '5〜10分', '教室', 'ペア', 'お題を書いた紙（くじ）', array['「好きな○○」「最近あった小さな出来事」など、軽いお題をあらかじめ紙に書いておく。', '1人ずつお題を引き、隣の人に向かって1分間話す。', '聞き手は相づちを打ったり、簡単な質問を1つ返したりする。']::text[], '話す内容を先生が決めておくことで、恥ずかしがる子でも話しやすくなります。', null, 8),
  ('seven-eleven-janken', 'セブンイレブンじゃんけん', '🖐', 'pair', '頭を使う・ゲーム系', '5分程度', '教室', 'クラス全体（ペアで実施）', 'なし', array['教室内を自由に歩き、ペアを見つける。', '「セブンイレブン、じゃんけん、ポン」のかけ声に合わせて、片手の指で0〜5の数字を出す。', '2人が出した数字を足して7になったら成功。握手して次のペアを探す。', '2回成功したら着席、というようにゴールを決めておくとまとまりやすい。']::text[], '数の合成の感覚も自然に使うので、算数の導入にも使いやすいアイスブレイクです。', null, 9),
  ('impulse-game', '電流ゲーム（インパルスゲーム）', '⚡', 'line', '落ち着く・集中系', '5〜10分', '教室', 'クラス全体（一列）', 'ストップウォッチ（あれば）', array['全員で手をつなぎ、一列に並ぶ。', '列の端の人がストップウォッチをスタートさせ、隣の人の手をきゅっと握る「合図」を送る。', '合図を受け取った人は、さらに隣の人へ順番に握って伝えていく。', '反対の端まで届いたらストップ。何秒で伝わったかを計り、次はもっと速く伝えられるか挑戦する。']::text[], '声を出さずに集中して取り組む活動なので、ざわついたクラスを落ち着かせたいときにも向いています。', null, 10),
  ('silent-birthday-line', '誕生日順ならび（サイレントラインナップ）', '🤫', 'line', '落ち着く・集中系', '10〜15分', '教室', 'クラス全体', 'なし（あれば紙と筆記具）', array['「これから一言も喋らずに、誕生日（1月1日〜12月31日）の順番に並んでください」とルールを伝える。', '子どもたちはジェスチャーや指の本数、空中に書く文字などで意思疎通しながら並ぶ。', '並び終わったら、端から順に誕生日を発表して答え合わせをする。']::text[], '「背の順」「50音順」などお題を変えると、何度でも遊べます。', '学級開きで「まだ誕生日を知らない同士」で行うと、自然と自己紹介のきっかけになります。', 11),
  ('who-am-i', 'わたしはだ〜れだ？', '❓', 'small-group', '頭を使う・ゲーム系', '10〜15分', '教室', '少人数〜クラス全体', 'お題を書く紙、箱', array['先生や代表の児童があらかじめ「クラスの誰か」を1人思い浮かべ、紙に書いて箱に入れておく。', '他の子どもたちが「好きな教科は？」「髪型は？」など、はい・いいえで答えられる質問をする。', '出題者は「はい」「いいえ」だけで答える。', '質問を重ねて、誰のことかを当てる。']::text[], '人数が多いクラスでは、グループに分かれて同時に行うと時間を短縮できます。', null, 12),
  ('dice-talk', 'サイコロトーク', '🎲', 'small-group', '会話・自己紹介系', '5〜10分', '教室', '5〜6人グループ', 'サイコロ（面にお題を書いておく）', array['5〜6人のグループで輪になって座る。', 'サイコロの面にあらかじめ「好きな〇〇」「最近楽しかったこと」などのお題を書いておく。', '順番にサイコロを振り、出た目のお題について30秒〜1分ほど話す。', '話し終わったら拍手をして、次の人に回す。']::text[], 'お題は「今日の朝ごはん」のような軽いものにすると、誰でも話しやすくなります。', null, 13),
  ('dont-laugh', 'わらっちゃダメゲーム', '😐', 'front', '落ち着く・集中系', '30秒×数回', '教室', 'クラス全体', 'ストップウォッチ（あれば）', array['先生が前に立ち、「制限時間30秒。この間、誰も笑ったり喋ったりしてはいけません」と伝える。', '先生（または代表の子）がおもしろい顔やジェスチャーをする。', '誰か1人でも笑ってしまったら、そこで終了。何秒もったか発表する。']::text[], '短時間で盛り上がるので、授業の合間の1〜2分の隙間時間にも使えます。', null, 14),
  ('one-leg-balance', '片足立ちチャレンジ', '🦵', 'scatter', '体を動かす系', '5〜10分', '教室（机・椅子を少しよける）', 'クラス全体', 'なし', array['全員が自分のスペースで片足立ちになる。', '「よーい、スタート」の合図で、誰が一番長く片足立ちを続けられるか競う。', '足がついてしまった人はそっと座る。最後まで立っていた人の勝ち。']::text[], '目をつぶって挑戦すると、さらに難易度が上がり盛り上がります（ぶつからない広さがある場合のみ）。', null, 15),
  ('gesture-game', 'ジェスチャーゲーム', '🎭', 'front', '頭を使う・ゲーム系', '10〜15分', '教室', 'クラス全体・チーム対抗も可', 'お題を書いたカード', array['出題者を1人決め、動物・スポーツ・職業などのお題カードを1枚引かせる。', '出題者は言葉を使わず、身振り手振りだけでお題を表現する。', '他の子どもたちが正解を当てる。当たったら次の出題者にバトンタッチ。']::text[], 'チーム対抗にして早押しにすると、より盛り上がります。', null, 16),
  ('good-and-new', 'グッド＆ニュー', '✨', 'small-group', '会話・自己紹介系', '5〜10分', '教室', '3〜5人グループ〜クラス全体', 'なし', array['グループ、またはクラス全体で輪になる。', '「24時間以内にあった、良かったこと・新しい発見」を1人ずつ発表する。', '発表が終わるたびに、みんなで拍手を送る。']::text[], '朝の会や週明けの1時間目にぴったりの、前向きな雰囲気づくり活動です。', null, 17),
  ('jumbo-janken', 'ジャンボじゃんけん', '🤸', 'front', '体を動かす系', '5〜10分', '教室・体育館どちらでも', 'クラス全体', 'なし', array['グー（体を丸めてしゃがむ）、チョキ（両手足を開いて片足を出す）、パー（両手両足を大きく広げる）のポーズを決めておく。', '先生 対 全員で「じゃんけんぽん」の掛け声に合わせて、体全体でポーズを取る。', '負けた人はその場に座り、勝ち残った人が最後まで続ける。']::text[], '体を大きく動かすので、座りっぱなしで疲れてきた時間帯にもおすすめです。', null, 18),
  ('mirror-game', 'ミラーゲーム', '🪞', 'pair', '体を動かす系', '5〜10分', '教室', 'ペア', 'なし', array['2人1組になって向かい合う。', '1人がリーダーになり、ゆっくり手や顔をいろいろな形に動かす。', 'もう1人は鏡になったつもりで、同じ動きをできるだけそっくり真似する。', '1分ほどたったら、リーダーを交代する。']::text[], '声を出さずに集中する活動なので、落ち着いた雰囲気づくりにも使えます。', null, 19),
  ('action-shiritori', '動作しりとり（プラスアクション）', '🔗', 'circle', '頭を使う・ゲーム系', '10分程度', '教室', '5〜8人グループ', 'なし', array['グループで輪になる。', '1人目が簡単な動作（例：手をたたく）をする。', '2人目は1人目の動作を繰り返してから、新しい動作を1つ足す。', '3人目はこれまでの動作をすべて順番に繰り返してから、また新しい動作を足す。', '動作を思い出せなくなった人が出たら、そこで1回終了して最初からやり直す。']::text[], '記憶力を使う頭の体操にもなる活動です。', null, 20),
  ('desert-island', '無人島に持っていくもの', '🏝', 'small-group', '会話・自己紹介系', '10分程度', '教室', '3〜4人グループ', 'なし（あれば紙と筆記具）', array['「無人島に3つだけ持っていけるとしたら何を持っていく？」というお題を出す。', '1人ずつ、持っていきたいものとその理由をグループ内で発表する。', '時間があれば、グループで「クラス全体で1つだけ選ぶなら？」を話し合ってもよい。']::text[], '答えに正解・不正解がないため、どんな子でも参加しやすい話題です。', null, 21),
  ('lion-hunt', '猛獣狩りに行こうよ', '🦁', 'scatter', '体を動かす系', '10〜15分', '教室・体育館', 'クラス全体', 'なし', array['先生と一緒に「猛獣狩りに行こうよ」の歌・かけ声のリズムに合わせて手拍子する。', '先生が動物の名前を言う（例：「ライオン」）。', '子どもたちは、その動物の文字数と同じ人数（「ライオン」なら4人）でグループを作る。', '人数が合わなかった人同士で、また新しいグループを作り直して続ける。']::text[], '自然と色々な子と関わるきっかけになる、学級開きの定番レクです。', null, 22),
  ('evolution-janken', '進化じゃんけん', '🐣', 'scatter', '体を動かす系', '10分程度', '教室・体育館', 'クラス全体', 'なし', array['全員「たまご」からスタートし、しゃがんだ姿勢で教室内を歩く。', '出会った人とじゃんけんをする。勝った人は「ひよこ」に進化して立ち姿勢に、負けた人はたまごのまま。', '同じ段階の人同士でじゃんけんを続け、勝つたびに「ひよこ→にわとり→人間→王様」のように進化していく。', '制限時間内に一番進化できた人の勝ち。']::text[], '負けても「たまごのまま次の相手を探す」だけなので、気軽に何度も参加できます。', null, 23),
  ('epicenter-game', '震源地ゲーム', '🌀', 'circle', '頭を使う・ゲーム系', '5〜10分', '教室', 'クラス全体', 'なし', array['鬼を1人決めて、廊下など見えない場所で待ってもらう。', '残りの子どもたちで輪になり、その中の1人を「震源地」に選ぶ。', '震源地の子が手拍子やポーズなどの動作をし、周りの子はそれをこっそり真似する。震源地は気づかれないように、時々動作を変える。', '鬼が呼ばれて輪の中に入り、動作を観察して「震源地」が誰かを当てる。']::text[], '全員が同じ動きをするので、震源地が誰かバレにくく、盛り上がります。', null, 24),
  ('yamanote-line-game', '山手線ゲーム（カテゴリーしりとり）', '🚃', 'circle', '頭を使う・ゲーム系', '5〜10分', '教室', '5人〜クラス全体', 'なし', array['「果物」「動物」「都道府県」などのお題（カテゴリー）を1つ決める。', '手拍子でリズムを取りながら、順番にお題に当てはまる言葉を1つずつ言っていく。', '言葉が思いつかなかったり、すでに出た言葉を言ってしまったりした人はそこで抜ける（またはお題を変えて続ける）。']::text[], '学習中の教科の言葉をお題にすると、楽しみながら復習にもなります。', null, 25),
  ('number-gathering', '数字集まりゲーム', '🔢', 'scatter', '体を動かす系', '5〜10分', '教室（机を少しよける）・体育館', 'クラス全体', 'なし', array['全員で教室内を自由に歩き回る。', '先生が数字を1つ言う（例：「4」）。', '子どもたちは、その人数ですばやくグループを作って座る。', '余ってしまった人たちも責めずに拍手で迎え、次の数字でまた歩き出す。']::text[], 'その日の学習内容に関わる数（例：グループ発表の人数）に合わせると、次の活動への移行もスムーズです。', null, 26),
  ('telephone-game', '伝言ゲーム', '📢', 'line', '頭を使う・ゲーム系', '10〜15分', '教室', '6〜8人のチーム対抗', 'お題の文章（先生が用意）', array['6〜8人のチームを作り、1列に並ぶ。', '先頭の人だけに、先生がお題の文章をこっそり見せる（または耳打ちする）。', '先頭から順番に、隣の人へ小声で聞いた内容を伝えていく。', '最後尾の人が聞いた内容を発表し、最初の文章とどれだけ合っているかを確認する。']::text[], '文章を少し長め・複雑にすると、伝わり方の違いがより面白くなります。', null, 27),
  ('maru-batsu-game', '○×ゲーム', '⭕', 'scatter', '体を動かす系', '5〜10分', '教室（○側・×側を決めておく）', 'クラス全体', 'なし（黒板に○×を書いておく）', array['教室の右側を「○」、左側を「×」と決める。', '先生がクイズや「はい・いいえ」で答えられる質問を出す（例：「消しゴムは文房具である」）。', '子どもたちは自分が正しいと思う方に移動する。', '答え合わせをして、外れた人は座る。数問繰り返して最後まで残った人が勝ち。']::text[], '学習内容の復習クイズにすると、体を動かしながら学びの振り返りにもなります。', null, 28),
  ('class-shiritori', 'クラスしりとり対決', '🔤', 'front', '頭を使う・ゲーム系', '5〜10分', '教室', 'クラス全体（列対抗など）', 'なし', array['列や班などでチームを分ける。', 'チームごとに、制限時間内でしりとりを続けて、何個の言葉をつなげられるか競う。', '「ん」で終わったらそこで終了。一番多くつなげたチームの勝ち。']::text[], '「生き物だけ」「3文字以上」のようにルールを1つ加えると、難易度が調整できます。', null, 29),
  ('back-writing-game', '背中で字あてゲーム', '✍️', 'pair', '落ち着く・集中系', '5〜10分', '教室', 'ペア', 'なし', array['2人1組になり、1人が背中を向ける。', '後ろの人が、相手の背中に指で1文字（ひらがな・数字など）を書く。', '背中を向けていた人は、何の文字を書かれたかを当てる。', '当たったら交代して、役割を入れ替える。']::text[], '声を出さずに集中して行う活動なので、教室を落ち着かせたいときにおすすめです。', null, 30),
  ('treasure-hunter', 'トレジャーハンター（宝物探し）', '💎', 'scatter', '頭を使う・ゲーム系', '5〜10分', '教室', 'クラス全体', '隠す小物（消しゴムなど）', array['「宝物役」を1人決めて、廊下など見えない場所で待ってもらう。', '残りの子どもたちで相談して、教室のどこかに小物（消しゴムなど）を隠す。', '宝物役を呼び戻し、みんなで拍手をする。宝物に近づいたら拍手を強く、遠ざかったら弱くして誘導する。', '拍手だけを頼りに、宝物を見つけられたら成功。']::text[], '声を出さず拍手だけで誘導するので、集中力を使う活動です。', null, 31),
  ('human-spot-the-difference', '人間まちがい探し（ペア編）', '🧐', 'pair', '会話・自己紹介系', '5分', '教室', 'ペア', 'なし', array['2人1組になって向かい合い、10秒ほどお互いの服装や持ち物をよく観察する。', '背中合わせになり、それぞれ自分の身なりを3か所こっそり変える（袖をまくる、時計を外すなど）。', '向き直って、相手のどこが変わったかをできるだけ多く当てる。']::text[], '「観察して覚える」練習になるので、集中力を高めたい朝の時間にもおすすめです。', null, 32),
  ('gyoza-janken', 'ギョウザジャンケン', '🥟', 'small-group', '体を動かす系', '3〜5分', '教室', '3人組', 'なし', array['3人組を作る。', '「せーの」の掛け声で、3人同時にグー・チョキ・パーのどれかを出す。', '3人とも同じ手（あいこ）になったら「ギョウザ！」と言って成功。あいこにならなければもう一度挑戦する。']::text[], '3人の気持ちが揃うと成功するゲームなので、グループのまとまりづくりにも使えます。', null, 33),
  ('one-in-a-hundred', '100分の1アンケート', '🌟', 'front', '会話・自己紹介系', '10分程度', '教室', 'クラス全体', 'なし', array['「クラスでただ1人だけ当てはまりそうなこと」を各自1つ考える（例：「左利きである」「ペットにカメを飼っている」）。', '1人ずつ発表し、他に同じ人がいないか手を挙げて確認する。', '本当に自分だけだった人には、みんなで拍手を送る。']::text[], '自分では気づいていない個性を発見できる、自己紹介にもぴったりな活動です。', null, 34),
  ('hum-the-intro-quiz', '歌ってイントロクイズ', '🎵', 'front', '頭を使う・ゲーム系', '5分程度', '教室', 'クラス全体', 'なし（音源不要）', array['出題者（先生や代表の子）が、知っている曲のイントロ部分を鼻歌やハミングで歌う。', '曲名が分かった人は手を挙げて答える。', '正解したら、その人が次の出題者になる。']::text[], '音源を用意しなくてもすぐできるので、ちょっとした隙間時間に向いています。', null, 35),
  ('silence-game', 'サイレンス', '🤐', 'front', '落ち着く・集中系', '30秒〜1分×数回', '教室', 'クラス全体', 'ストップウォッチ（あれば）', array['「これから30秒間、誰も物音を立てないでください」とルールを伝える。', 'タイマーをスタートし、全員で静かに座って過ごす。', '物音が聞こえたらそこで終了。何秒間静かでいられたかを発表する。']::text[], '騒がしくなった後の切り替えや、落ち着いて次の活動に入りたいときに効果的です。', null, 36),
  ('name-talk', 'ネームトーク', '📛', 'circle', '会話・自己紹介系', '5〜10分', '教室', 'クラス全体〜グループ', 'なし', array['輪になって座る（またはそのまま着席のままでもよい）。', '先生が誰か1人の名前を呼ぶ。', '呼ばれた子は「はい」と返事をしたあと、決めておいたお題（好きな食べ物・好きな色など）を一言付け加える。', '次々に名前を呼んで、みんなに順番が回るようにする。']::text[], '毎回お題を変えれば、学期を通して繰り返し使える定番の自己紹介ネタになります。', null, 37),
  ('quiz-don', 'クイズでドン！', '📝', 'front', '頭を使う・ゲーム系', '5分程度', '教室', 'クラス全体', 'なし', array['直前の授業や単元の内容から、○×クイズや3択クイズを2〜3問用意する。', '問題を出し、子どもたちは手を挙げる・体で○×を表すなどの方法で答える。', '答え合わせをしながら、簡単に内容を振り返る。']::text[], 'アイスブレイクと授業の復習を同時に行える、忙しい時間割の合間に便利な活動です。', null, 38),
  ('numbers-game', 'ナンバーズ', '🔢', 'front', '頭を使う・ゲーム系', '5分程度', '教室', 'クラス全体', '紙とペン', array['1〜10など範囲を決め、好きな数字を1つ紙に書く（他の人には見せない）。', 'せーので全員が数字を発表する。', '他の誰とも被らなかった数字の中で、一番小さい数字を選んだ人が勝ち。']::text[], '「みんなが選びそうな数字を予想して外す」という、心理戦の要素がある頭の体操です。', null, 39),
  ('same-cut', 'セイムカット', '✂️', 'front', '頭を使う・ゲーム系', '5〜10分', '教室', 'クラス全体', '紙とペン', array['1〜20など範囲を決め、その中から好きな数字を3つ紙に書く。', '順番に発表していき、他の人と同じ数字が出たら、その数字は「カット」（無効）になる。', '誰とも被らなかった数字の合計が一番大きい人が勝ち。']::text[], '「ナンバーズ」に慣れてきたクラスにおすすめの、少し発展したバージョンです。', null, 40),
  ('telepathy-game', 'テレパシーゲーム', '🔮', 'small-group', '頭を使う・ゲーム系', '5〜10分', '教室', '3〜4人グループ', '紙とペン', array['3〜4人のグループを作る。', '「好きな色は？」「好きな給食のメニューは？」などのお題を出す。', 'せーので、それぞれ紙にお題の答えを1つ書く。', 'せーので紙を見せ合い、全員の答えが一致したら「テレパシー成功」。']::text[], '何問か続けて出題し、何回成功できるか挑戦すると盛り上がります。', null, 41),
  ('blind-drawing-song', '見ないで絵描き歌', '🎨', 'front', '頭を使う・ゲーム系', '5〜10分', '教室', 'クラス全体', '紙とペン', array['先生（または知っている子）が、絵描き歌を「歌だけ」歌う（お手本の絵は見せない）。', '子どもたちは歌詞だけを頼りに、自分の紙に絵を描いていく。', '歌い終わったら、実際の絵と見比べて答え合わせをする。似ている・似ていないで盛り上がる。']::text[], '図工の授業の導入や、聞く力を使う活動としても使えます。', null, 42),
  ('aiue-battle', 'あいうえバトル', '🔤', 'pair', '頭を使う・ゲーム系', '5〜10分', '教室', 'ペア', 'なし（あれば紙とペン）', array['2人1組になる。', '「7文字以内の食べ物」のように、文字数とジャンルを決めたお題を出す。', '2人とも、お題に当てはまる言葉を1つ頭の中で決める（相手には言わない）。', '交互にひらがなを1文字ずつ言っていく。自分が決めた言葉の中に、相手が言った文字があれば「あります」と公開し、どの位置の文字かを伝える。', '同じように、自分が言った文字が相手の言葉にもあれば、相手も公開していく。', '公開された文字をヒントにしながら、先に相手の言葉を言い当てた方が勝ち。']::text[], '濁点・半濁点は区別しない（「か」と「が」は同じ文字として扱う）ルールにすると、分かりやすく進められます。', 'お題を「動物」「教科」「都道府県」などに変えれば、何度でも繰り返し遊べます。', 43),
  ('three-hint-quiz', '私は誰でしょう？3ヒントクイズ', '🕵️', 'front', '頭を使う・ゲーム系', '5〜10分', '教室', 'クラス全体', 'なし', array['先生がクラスの誰か（または有名人・キャラクター）を1人思い浮かべる。', '「好きな教科は算数です」のように、ヒントを1つずつ、合計3つまで出す。', '子どもたちは挙手して、誰のことかを予想して答える。']::text[], 'ヒントの順番を「分かりにくい→分かりやすい」にすると、最後まで盛り上がります。', null, 44),
  ('minority-game', 'マイノリティゲーム', '🙋', 'front', '頭を使う・ゲーム系', '5〜10分', '教室', 'クラス全体', 'なし（あれば紙とペン）', array['「朝はパン派？ごはん派？」のように、2択で答えられるお題を出す。', '全員が同時に、自分の答えの方に手を挙げる（または移動する）。', '人数が少なかった方を選んだ人が勝ち抜けとなる。', 'お題を変えながら数回繰り返し、最後まで勝ち抜けた人を称える。']::text[], 'みんなと違う方を選ぶのが得意な子も活躍できるゲームなので、いろいろな子にスポットが当たります。', '勝ち負けを競わず、「なぜその答えを選んだか」を隣同士で話す時間にしても盛り上がります。', 45),
  ('tongue-twister-ranking', '早口ことば番付', '👅', 'front', '頭を使う・ゲーム系', '5〜10分', '教室', 'クラス全体（1人ずつ挑戦）', '早口ことばを書いたカードや黒板', array['「生麦生米生卵」のような早口ことばをいくつか用意しておく。', '1人ずつ前に出て、決めた早口ことばを3回続けて言う。', '3回ともかまずに言えたら合格。合格するごとに、より難しい早口ことばに挑戦できる「番付」を用意する。', 'どこまで昇格できたか、クラスで拍手して称え合う。']::text[], '失敗しても笑いが起きるゲームなので、「間違えても大丈夫」という空気づくりにぴったりです。', 'ペアやグループで交代しながら挑戦する形式にすると、待ち時間が減ります。', 46),
  ('picture-shiritori', '絵しりとり', '🖍', 'small-group', '頭を使う・ゲーム系', '10〜15分', '教室', '3〜5人グループ', '紙とペン', array['3〜5人のグループを作り、1枚の紙を順番に回す。', '1人目が言葉を絵だけで描く（文字は書かない）。', '2人目は前の絵が何を表しているかを考え、その言葉の最後の音から始まる新しい絵を描き足す。', '最後まで回したら、それぞれの絵が何を表していたかを発表し合う。']::text[], '絵の上手さは関係ないので、「伝わるかどうか」を楽しむ雰囲気にすると誰でも参加しやすくなります。', '「ん」がつく絵を描いてしまったら負け、というルールを加えると通常のしりとりに近づきます。', 47),
  ('picture-telephone-game', 'お絵かき伝言ゲーム', '🖼', 'line', '頭を使う・ゲーム系', '10〜15分', '教室', '6〜8人のチーム対抗', 'チームごとに紙とペン', array['6〜8人のチームを作り、1列に並ぶ。', '先頭の人だけに、先生がお題の言葉（例：「サッカーをしているゾウ」）をこっそり伝える。', '先頭の人はお題を絵だけで紙に描き、次の人に見せる。見た人はその絵が何かを考え、言葉に直して次の人にだけこっそり伝える。', '「言葉で伝える」と「絵で伝える」を交互に繰り返し、最後の人が答えた言葉が最初のお題とどれだけ合っているかを確認する。']::text[], '絵と言葉の伝言が交互に入ることで、通常の伝言ゲームより早い段階で内容が変化しやすく、盛り上がります。', null, 48),
  ('word-bingo', 'ことばビンゴ', '🎯', 'front', '頭を使う・ゲーム系', '10〜15分', '教室', 'クラス全体', 'ビンゴ用の枠を書いた紙（3×3や4×4のマス目）、ペン', array['「好きな給食メニュー」など、テーマを1つ決める。', '各自、マス目にテーマに合う言葉を自由に書き込む。', '1人ずつ順番に、自分が書いた言葉を発表する。発表された言葉が自分のマスにもあれば、〇をつける。', '縦・横・斜めのいずれかが早く揃った人から「ビンゴ！」と声を上げる。']::text[], '国語の新出漢字や社会科の用語をテーマにすれば、学習内容の復習としても使えます。', null, 49),
  ('riddle-relay', 'なぞなぞリレー', '🧩', 'line', '頭を使う・ゲーム系', '10〜15分', '教室', '4〜8人のチーム対抗', 'なぞなぞ問題（先生が用意）', array['チームに分かれて1列に並ぶ。', '先生が1問なぞなぞを出す。各チームの先頭の人だけが答えてよい。', '正解したら次の人にバトンタッチして次の問題へ、不正解なら同じチームの次の人がもう一度同じ問題に挑戦する。', '決めた問題数の中で、正解数が一番多いチームの勝ち。']::text[], '考える時間を少し設けると、答えを言う前に落ち着いて相談できます。', null, 50),
  ('memory-match', '神経衰弱', '🃏', 'small-group', '頭を使う・ゲーム系', '10〜15分', '教室', '2〜4人グループ', '同じ絵柄が2枚ずつになるカード（トランプでも可）', array['カードをすべて裏返し、机の上に並べる。', '順番に2枚ずつめくり、同じ絵柄（同じ数字）のペアが揃ったらそのカードをもらえて、もう一度挑戦できる。', '揃わなかったら元の場所に裏返して戻し、次の人の番になる。', 'カードがなくなるまで続け、一番多くペアを集めた人が勝ち。']::text[], '同じ読みの漢字カードにすれば、国語の学習にもつながります。', null, 51),
  ('handkerchief-drop', 'ハンカチ落とし', '🧣', 'seated-circle', '体を動かす系', '10〜15分', '教室（椅子を外向きの円に）', 'クラス全体', 'ハンカチ（またはタオル）', array['全員が外向きに円になって座り、鬼を1人決める。', '鬼はハンカチを持って円の外側を歩き、気づかれないように誰か1人の後ろにそっと落とす。', '落とされたことに気づいた人はハンカチを拾い、鬼を追いかけてタッチする。タッチされる前に鬼が空いた場所に座れたら成功、座れなければ鬼を交代。', '気づかれずに一周されてしまった場合は、その人が次の鬼になる。']::text[], '後ろを気にしすぎず前を向いて座ることを事前に伝えると、スムーズに進みます。', null, 52),
  ('rhythm-four', 'リズム4', '🥁', 'circle', '頭を使う・ゲーム系', '5〜10分', '教室', '5〜8人グループ', 'なし', array['円になり、「もも・もも・たろう・たろう」のように4拍のリズムに合わせて手拍子しながら自分の名前を2回言う。', '続けて、その場にいる誰か1人の名前を2回、同じリズムで呼ぶ。', '呼ばれた人は、リズムを止めずに自分の名前→誰かの名前、の順で続けていく。', 'リズムが崩れたり止まったりした人が出たら、そこで一区切りとして最初からやり直す。']::text[], '名前の代わりに好きな食べ物や動物の名前にすると、まだ名前を覚えていないクラス替え直後でも遊びやすくなります。', null, 53),
  ('kame-kame-pyon', 'かめかめぴょん', '🐢', 'pair', '体を動かす系', '5分程度', '教室', 'ペア', 'なし', array['2人1組になり、向かい合って片手を軽く握って前に出す。', '「かめかめぴょん」のかけ声に合わせて、それぞれ指を1〜5本の好きな本数だけ立てる。', '2人が立てた指の本数が同じだったら「あいこ」でもう一度、違ったら事前に決めたルール（多い方の勝ちなど）で勝敗を決める。', '何度か繰り返し、勝った回数を数える。']::text[], 'じゃんけんに飽きたときの変化球として、すきま時間にぴったりです。', null, 54),
  ('pose-matching-game', 'ポーズ合わせゲーム', '🤾', 'front', '体を動かす系', '5〜10分', '教室', 'クラス全体（ペア〜グループでも可）', 'なし', array['「スポーツ」「動物」などのお題を1つ出す。', '「せーの」の合図で、全員が同時にお題に合うポーズを取る。', '周りを見て、多くの人と同じポーズになれていたら成功。', 'お題を変えて何度か繰り返す。']::text[], '何も相談せずに気持ちを合わせるゲームなので、テレパシーゲームの体を動かすバージョンとして使えます。', null, 55),
  ('signal-game', '信号ゲーム', '🚦', 'line', '体を動かす系', '5〜10分', '教室（机を少しよける）・体育館', 'クラス全体', 'なし', array['全員が横一列に並ぶ。', '先生が「青」と言ったら前に進み、「黄色」と言ったら後ろに下がり、「赤」と言ったら止まる、というルールを伝える。', '先生の合図に合わせて、それぞれの動きをする。', '合図と違う動きをしてしまった人はスタート地点に戻る。先に先生のところまでたどり着けたら成功。']::text[], '合図の順番をわざと入れ替えたり早口にしたりすると、とっさの判断力が試されて盛り上がります。', null, 56),
  ('shadow-tag', '影ふみ鬼', '🌗', 'scatter', '体を動かす系', '10〜15分', '校庭・体育館（晴れて影がはっきり出るとき）', 'クラス全体', 'なし', array['鬼を1〜2人決める。', '鬼以外の子は逃げ、鬼は他の子の「影」を踏むことを目指す。', '影を踏まれた子は次の鬼になる。', 'ぶつからないよう周りをよく見て動くことを事前に確認する。']::text[], '天候によって遊べない日もあるため、晴れの日の外遊びの選択肢の1つとして用意しておくと便利です。', null, 57),
  ('color-tag', '色鬼', '🎨', 'scatter', '体を動かす系', '10〜15分', '校庭・体育館', 'クラス全体', 'なし', array['鬼を1〜2人決める。', '鬼が「赤！」のように色を1つ指定する。', '鬼以外の子は、指定された色のもの（服・持ち物・遊具など）に急いでタッチして安全になる。', '色にタッチできず鬼にタッチされてしまった子が、次の鬼になる。']::text[], '身の回りの色を素早く探す活動なので、外遊び前の準備運動代わりにもおすすめです。', null, 58),
  ('chopstick-circle', 'わりばしサークル', '🥢', 'circle', '落ち着く・集中系', '10分程度', '教室', '5〜8人グループ', '割りばし（人数分）', array['グループで円になり、隣の人と割りばしの端を人差し指1本ずつではさんで支え合う。', '手を使わず、割りばしを落とさないように輪を保つ。', '慣れてきたら、円のまま全員でゆっくり立ったり座ったりしてみる。', '割りばしを落とさずにできたら成功。落ちてしまったらそこからもう一度挑戦する。']::text[], '声を掛け合いながらゆっくり動くと落ちにくくなるので、協力してタイミングを合わせる練習になります。', null, 59),
  ('pencil-nose-balance', '鼻の下えんぴつ', '✏️', 'front', '落ち着く・集中系', '3〜5分', '教室', 'クラス全体（同時に挑戦）', '鉛筆（1人1本）', array['1人1本、鉛筆を用意する。', '鼻と唇の間（鼻の下）に鉛筆をはさんでバランスを取る。', '手を使わずに何秒キープできるかに挑戦する。', '落ちてしまったらそっと座る。一番長くキープできた人の勝ち。']::text[], '静かに集中して取り組む活動なので、ざわついた教室を落ち着けたいときにも使えます。', null, 60),
  ('eyes-closed-high-five', '目をつぶってハイタッチ', '🙌', 'pair', '体を動かす系', '5分程度', '教室', 'ペア', 'なし', array['2人1組になって向かい合う。', '2人とも目を閉じて、片手を軽く前に出す。', '先生の「せーの」の合図で、目を閉じたままお互いの手を合わせてハイタッチを狙う。', 'うまく手が合ったら成功。何回か挑戦して成功率を競っても楽しい。']::text[], '見えない状態で相手の位置を予想する遊びなので、ビート５が好きなクラスにもおすすめです。', null, 61),
  ('reflex-showdown', 'とっさの反射しょうぶ（にぎって・ふんで・ひじタッチ）', '⚡', 'pair', '体を動かす系', '5分程度', '教室', 'ペア', 'なし', array['2人1組になり、向かい合う。', '「にぎって勝負」なら両手を軽く合わせ、先生の合図で先に相手の手を握れた方が勝ち。', '「ふんで勝負」なら足を軽く近づけ、合図で先に相手の足の甲を踏めた方が勝ち。', '「ひじタッチ勝負」ならひじを軽く近づけ、合図で先に相手のひじにタッチできた方が勝ち。好きな種目を選んで対戦する。']::text[], '強く握ったり踏んだりしないよう、事前に「そっとでOK」というルールを伝えておくと安全に楽しめます。', null, 62),
  ('paper-slash-catch', '真剣白刃取り', '📄', 'pair', '体を動かす系', '5分程度', '教室', 'ペア', '紙を細長く切ったもの（1本）', array['2人1組になり、1人が細長く切った紙を縦に持つ。', 'もう1人は、紙の下の方に指を軽く添えて構える。', '紙を持っている人が、いつ手を離すかを予告せずに落とす。', '受け手は紙が落ち切る前に、指で挟んでキャッチできたら成功。何回か交代しながら挑戦する。']::text[], '落ちる瞬間を集中して見る遊びなので、授業の切り替え前に集中力を高めたいときにも使えます。', null, 63),
  ('dots-and-boxes', '陣取り点つなぎゲーム（ドットアンドボックス）', '🔲', 'pair', '頭を使う・ゲーム系', '10〜15分', '教室', '2人', '方眼状に点を書いた紙、ペン（2色）', array['紙に点を格子状に並べて書いておく（例：5×5の点）。', '2人交代で、隣り合う点と点を1本の線でつなぐ。', '自分の線で四角形（マス）が完成したら、そのマスに自分の印をつけてもう一度線を引ける。', 'すべての点がつながったら終了し、自分の印が多い方の勝ち。']::text[], '先を読む力が育つゲームなので、算数の図形学習の合間の一息にもおすすめです。', null, 64),
  ('origami-time-attack', 'お題おりがみタイムアタック', '🎏', 'small-group', '落ち着く・集中系', '10分程度', '教室', '個人〜小グループ', '折り紙', array['「つる」「やっこさん」など、みんなが折り方を知っているお題を1つ決める。', '「よーい、スタート」の合図で、制限時間内に折り上げることに挑戦する。', 'できあがった作品をお互いに見せ合う。', '折り方が分からない子には、早く折れた子が教えてあげる時間を作ってもよい。']::text[], '静かに手を動かす活動なので、集中力を落ち着けたい時間にも向いています。', null, 65),
  ('partner-introduction', '他己紹介', '🗣', 'pair', '会話・自己紹介系', '10〜15分', '教室', 'ペア', 'なし（あればメモ用紙）', array['2人1組になり、お互いに好きなことや得意なことなどを2〜3分ずつインタビューし合う。', '聞いた内容を忘れないよう、簡単にメモを取ってもよい。', '順番にペアの前に立ち、聞いた内容をもとに相手を「他己紹介」する。', '紹介された本人が、内容に補足や訂正をしてもよい。']::text[], '自分の言葉ではなく相手の言葉で紹介されるので、恥ずかしがり屋の子でも自己紹介がしやすくなります。', '学級開き直後に行うと、名前だけでなく人となりも早く知り合うきっかけになります。', 66)
) as seed(slug, title, emoji, scene, category, duration, place, group_size, materials, steps, tip, variation, sort_order)
where not exists (select 1 from icebreakers);

insert into recreations (slug, title, emoji, scene, category, grades, occasions, duration, prep, place, places, group_size, materials, steps, tip, variation, safety, inclusion, icebreaker_slug, sort_order)
select * from (values
  ('ice-tag', 'こおり鬼', '🧊', 'tag', 'そとあそび（鬼ごっこ系）', array['低学年', '中学年', '高学年']::text[], array[]::text[], '10〜15分', 'なし', '校庭・体育館', array['校庭', '体育館']::text[], 'クラス全体', 'なし（あればビブスや赤白帽）', array['鬼を2〜3人決め、「にげてよい場所」をはっきり決める（コーンなどで囲んで見えるようにする）。', '鬼にタッチされた人は「氷」になり、両手を広げてその場から動けなくなる。', '逃げている人が氷になった人にタッチすると、助けられて復活できる。', '3分たったら一度止めて鬼を交代する。これを3〜4回くり返し、最後の回で動ける人が残っていたら逃げる側の勝ち。']::text[], '鬼は人数の1割くらい（30人なら3人）が目安。赤白帽の色を変えると、誰が鬼か一目で分かります。', '助けるときに「氷になった人の手にタッチしながら名前を呼ぶ」ルールにすると、助け合いの声が増えます。', '走ってよい範囲をコーンで区切り、遊具・段差・側溝のそばは範囲から外しておきます。', null, null, 1),
  ('multiply-tag', '増え鬼', '👥', 'tag', 'そとあそび（鬼ごっこ系）', array['低学年', '中学年', '高学年']::text[], array[]::text[], '10分程度', 'なし', '校庭・体育館', array['校庭', '体育館']::text[], 'クラス全体', 'なし（あればビブスや赤白帽）', array['鬼を1〜2人決め、逃げる範囲を決める。', 'タッチされた人はその場で鬼の仲間になり、一緒に追いかける。', 'だんだん鬼が増えていき、最後まで逃げ切った人が勝ち。', '最後の1人が決まったら、その人を次のゲームの最初の鬼にする。']::text[], '鬼になった人は帽子を赤にするなど、見た目ですぐ分かるようにしておくと混乱しません。', '残りの人数が少なくなったら範囲を狭めると、終わる時間をそろえやすくなります。', '鬼が増えると囲い込みが起きやすいので、「後ろから強く押さない」ことを最初に確認します。', null, null, 2),
  ('hand-chain-tag', '手つなぎ鬼', '🤝', 'tag', 'そとあそび（鬼ごっこ系）', array['低学年', '中学年']::text[], array['学級開き']::text[], '10〜15分', 'なし', '校庭・体育館', array['校庭', '体育館']::text[], 'クラス全体', 'なし', array['鬼を2人決め、手をつないだまま追いかける。', 'タッチされた人は鬼と手をつなぎ、鬼のグループが増えていく。', '鬼が4人になったら2人ずつの2組に分かれ、それぞれ別々に追いかける。', '最後まで逃げ切った人が勝ち。']::text[], '手を離したらタッチは無効、というルールにすると、鬼同士が声をかけ合って動くようになります。', '人とふれ合うのが苦手な子がいる場合は、手をつなぐかわりに1本のタスキの両端を持つ形にすると参加しやすくなります。', '鬼ごっこの中でも転倒が起きやすい遊びです。「走りながら急に方向を変えない」「手を強く引かない」「引っぱられたら手を離してよい」の3つを先に約束します。', null, null, 3),
  ('high-tag', '高鬼', '🧗', 'tag', 'そとあそび（鬼ごっこ系）', array['中学年', '高学年']::text[], array[]::text[], '10〜15分', '校内のきまりの確認（事前）', '校庭（段差やベンチのある場所）', array['校庭']::text[], 'クラス全体', 'なし', array['先生が「乗ってよい場所」と「乗ってよい高さ」を先に指定する（遊具に乗ってよいかは学校のきまりを確認しておく）。', '鬼を1〜2人決め、指定された高い所に乗っている間はタッチされない、というルールを確認する。', '高い所にいられるのは10秒まで。鬼が声に出して数え終わったら、必ず下りて移動する。', 'タッチされた人が次の鬼になる。']::text[], '「10秒たったら下りる」ルールがないと全員が動かなくなります。鬼が声に出して数えるとスムーズです。', null, '乗ってよいのは、ひざ〜腰くらいまでの安定した場所だけにします。飛び降り禁止も先に伝えておきます。遊具に乗る遊びを禁止している学校もあるので、実施前に校内のきまりを確認してください。雨上がりや朝の冷えこみで遊具がぬれている日は行いません（すべって落ちます）。', '高い所に乗るのがむずかしい子がいるときは、安全地帯を「高い所」ではなく「決めた色のもの」にかえる（＝色鬼にする）と、同じルールで一緒に遊べます。', null, 4),
  ('banana-tag', 'バナナ鬼', '🍌', 'tag', 'そとあそび（鬼ごっこ系）', array['低学年', '中学年']::text[], array[]::text[], '10〜15分', 'なし', '校庭・体育館', array['校庭', '体育館']::text[], 'クラス全体', 'なし', array['鬼を2〜3人決める。', 'タッチされた人は両手を上にあげて合わせ、「バナナ」の形で止まる。', '逃げている人が2人がかりで両側から腕を下ろす（皮をむく）と、復活できる（1・2年生とやるときは、1人で下ろしてよいことにする）。', '3分ほどで区切り、鬼を交代して何回か行う。']::text[], '助けるのに2人必要なので、自然と声をかけ合うようになります。低学年にも人気のルールです。', '「助けるのは1人でOK」にすると難しさが下がり、1・2年生でも遊びやすくなります。', '腕を下ろすときに強く引っぱらないよう、やさしく下ろす様子を実演して見せておきます。', null, null, 5),
  ('color-tag', '色鬼', '🎨', 'field', 'そとあそび（鬼ごっこ系）', array['低学年', '中学年', '高学年']::text[], array[]::text[], '10〜15分', 'なし', '校庭・体育館', array['校庭', '体育館']::text[], 'クラス全体', 'なし', array['鬼を1〜2人決め、逃げる範囲を決める。', '鬼が「赤！」のように色を1つ言う。', 'ほかの人は、その色のもの（服・持ち物・遊具など）にさわれれば安全。さわっている間は鬼にタッチされない。', '色にさわれないまま鬼にタッチされた人が、次の鬼になる。']::text[], '学級レクとして長めに遊ぶときは「同じ色は2回まで」と決めると、同じ場所に固まらず動きが出ます。', '「赤と青の両方にさわる」など2色出しにすると、高学年でも手ごたえのある遊びになります。', '色を探して急に立ち止まる子がいるため、範囲を広めにとり、走る向きを確認しておきます。', null, 'color-tag', 6),
  ('shadow-tag', '影ふみ鬼', '🌗', 'field', 'そとあそび（鬼ごっこ系）', array['低学年', '中学年', '高学年']::text[], array['学級開き']::text[], '10〜15分', 'なし', '校庭（晴れて影がはっきり出る日）', array['校庭']::text[], 'クラス全体', 'なし', array['鬼を2〜3人決め、逃げる範囲を決める。', '鬼は体ではなく、相手の「影」を踏むことを目指す。', '影を踏まれた人が次の鬼になる。木かげや建物のかげに入っている間は安全。', '「かげに入っていられるのは10秒まで」と決めておくと、動きが止まらない。']::text[], '体にさわらない鬼ごっこなので、人にふれられるのが苦手な子も参加しやすい遊びです。', null, '下を向いて走りがちなので、始める前に「顔を上げて、人とぶつからないように」と確認します。', null, 'shadow-tag', 7),
  ('cross-tag', '十字鬼', '✚', 'field', 'そとあそび（鬼ごっこ系）', array['中学年', '高学年']::text[], array['お楽しみ会']::text[], '15〜20分', 'ラインを引く（体育館のラインを使えば0分／校庭は10分）', '校庭・体育館', array['校庭', '体育館']::text[], 'クラス全体（2チーム）', 'ライン（石灰・体育館のラインでも可）', array['地面に大きな十字の線を引き、鬼はその線の上だけを動ける、と決める。', '鬼チーム（4〜6人）と逃げるチームに分かれる。逃げる人は、十字で区切られた4つの部屋を線をまたいで移動する。', '線をまたぐ瞬間に鬼にタッチされたらアウト。コートの外で待つ。', '制限時間で何人残ったかを数え、チームを交代して同じ時間だけ行う。']::text[], '鬼は線の上しか動けないので、走るのが速くない子でも活躍できます。作戦タイムを入れるとさらに盛り上がります。体育館でやるときは、十字の線を端から端まで大きくとらないと、1つの部屋がすぐ窮屈になります。', '十字ではなく「田」の字にすると部屋が増え、高学年向けの難しいコースになります。「決めた回数だけ部屋を移動できたら逃げる側の勝ち」という数え方もあります。', '線の上で正面からぶつかりやすいので、鬼の人数を増やしすぎないようにします。暑い時期は、とちゅうで一度止めて水分をとる時間をつくります。暑さ指数が高い日は、時間を短くするか日かげでできる遊びに変えてください。', null, null, 8),
  ('tail-tag', 'しっぽ取り', '🎽', 'field', 'そとあそび（鬼ごっこ系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会']::text[], '10〜15分', 'タスキを人数分そろえる（5分）', '校庭・体育館', array['校庭', '体育館']::text[], 'クラス全体', '人数分のタスキ（すずらんテープや古布でも可）', array['全員が、ズボン（体操服の下）の後ろにタスキを軽くはさんで「しっぽ」にする。服の中に入れたり、結んだりしない。', '合図で一斉に始め、ほかの人のしっぽを取りに行く。取られた人も、持っているしっぽを1本わたせばすぐ復活できる（1本もないときは先生からもらう）。', 'タイマーが鳴ったら、手元にあるしっぽの本数を数える。', 'チーム対抗にする場合は、チームごとの合計本数で勝敗を決める。']::text[], 'しっぽは「軽くはさむだけ」。強く結ぶと引っぱり合いになり危険なので、先生が一度やって見せてから配ります（低学年は言葉だけでは力加減が伝わりません）。', '脱落ありのルールにすると勝負がはっきりしますが、待ち時間が長くなります。その場合は1回を3分ほどに区切ってください。', '服やズボンをつかむのは禁止、取ってよいのは外に出ているしっぽだけ、というルールにします。', null, null, 9),
  ('keidoro', 'けいどろ（どろけい）', '🚓', 'tag', 'そとあそび（鬼ごっこ系）', array['中学年', '高学年']::text[], array['お楽しみ会']::text[], '20〜30分', 'ビブスとコーンの用意（5分）', '校庭', array['校庭']::text[], 'クラス全体（2チーム）', 'ビブスや赤白帽、牢屋の目印になるコーン', array['警察チームと泥棒チームに分かれ、牢屋（つかまった人が入る場所）を決める。', '警察は泥棒を追いかけ、タッチしたら牢屋へ連れて行く。', 'つかまっていない泥棒が牢屋の人にタッチすると脱出できる（全員か1人かは先に決めておく）。', '制限時間内に泥棒を全員つかまえられたら警察の勝ち。役を交代してもう1回行う。']::text[], '牢屋を守る警察（牢屋番）を置くかどうかで難しさが大きく変わります。最初は「牢屋番あり」がおすすめです。', '脱出できる人数を「1回につき1人」にすると、警察チームが勝ちやすくなります。', 'つかまえるときは「タッチだけ」。腕をつかんで引っぱらないことを、始める前に全員で確認します。暑い時期は、とちゅうで一度止めて水分をとる時間をつくります。暑さ指数が高い日は、時間を短くするか日かげでできる遊びに変えてください。雨上がりでぬかるんでいる日は、すべって転ぶので校庭では行いません。', null, null, 10),
  ('daruma', 'だるまさんがころんだ', '🧍', 'field', 'そとあそび・体育館（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array['学級開き']::text[], '10〜15分', 'なし', '校庭・体育館', array['校庭', '体育館']::text[], 'クラス全体', 'なし', array['鬼を1人決め、壁や木の方を向いて立つ。ほかの人は離れたスタートラインに並ぶ。', '鬼が「だるまさんがころんだ」と言っている間だけ、みんなは鬼に近づける。鬼が振り向いたときに動いていた人は、鬼と手をつないでつかまる。', 'だれかが鬼とつかまった人の手を切って「切った！」と言ったら、全員でスタートラインへ逃げる。', '鬼が「ストップ」と言ったら全員止まり、鬼は決めておいた歩数（3歩・5歩など）だけ進んでタッチする。届いた人が次の鬼。']::text[], '「ストップのあと何歩進めるか」を最初に決めておかないと、必ずもめます。低学年なら3歩、高学年なら5歩が目安です。', '5・6年でやるときは「だるまさんが笑った」（鬼が言った言葉の通りにポーズを取る）を基本ルールにしてください。そのままの形だと、高学年にはすぐ飽きられます。', '逃げる方向に段差や壁がないかを確認し、スタートラインは壁から十分に離してとります。', null, null, 11),
  ('can-kick', '缶けり', '🥫', 'field', 'そとあそび・体育館（体を動かす系）', array['中学年', '高学年']::text[], array[]::text[], '20〜30分', '目印と範囲の確認（5分）', '校庭（先生から見わたせる範囲）', array['校庭']::text[], 'クラス全体', 'コーン（缶の代わり。空き缶は切り口でけがをするので使わない）', array['中央にコーンを置き、鬼を1人決める。かくれてよい範囲を先生が言い、先生のあとについてみんなでもう一度言ってから始める。', '鬼が30数えている間にかくれる。鬼は見つけた人の名前を言いながらコーンにタッチし、見つかった人はコーンのそばで待つ。', 'かくれている人が鬼より先にコーンをたおすと、つかまっていた人は全員逃げ直しできる。', '全員を見つけられたら鬼を交代する。']::text[], 'かくれてよい範囲を先に決めておかないと、探すのに時間がかかりすぎます。校庭の半分など、先生が立ったまま見わたせる広さに区切りましょう。', '体育館なら、マットや跳び箱の陰を使って同じように遊べます。', '倉庫の陰・校舎の裏・駐車場など、先生の目が届かない場所は範囲に入れません。人数が多い日は、かくれる人を半分にして2回戦にすると見守りやすくなります。暑い時期は、とちゅうで一度止めて水分をとる時間をつくります。暑さ指数が高い日は、時間を短くするか日かげでできる遊びに変えてください。', null, null, 12),
  ('hana-ichimonme', '花いちもんめ', '🌸', 'team-line', 'そとあそび・体育館（体を動かす系）', array['低学年', '中学年']::text[], array['雨の日']::text[], '10〜15分', 'なし（教室でやるときは机を下げて5分）', '校庭・体育館・教室（広く使えるとき）', array['校庭', '体育館', '教室']::text[], 'クラス全体（2チーム）', 'なし', array['2チームに分かれ、手をつないで向かい合って並ぶ。低学年には、先に「ほしい人をよび合って、じゃんけんで仲間をふやしていく遊びだよ」と、ひと言で説明してから始める。', '「かってうれしい はないちもんめ」「まけてくやしい はないちもんめ」と歌いながら、交互に前へ進んだり下がったりする。', '「あの子がほしい」「あの子じゃわからん」「そうだんしましょ」「そうしましょ」と歌でやりとりし、チームで相談する。ほしい人は、名前ではなく「赤い服の人」「白いくつ下の人」のように特徴で伝える（本来は名前を呼ぶ遊びですが、名指しを避けるための形です）。', '指名された2人がじゃんけんをし、勝ったチームにその人が移る。人数が多くなったチームの勝ち。']::text[], '名前で指名すると「あの子だと勝てない」という相談になりがちです。特徴で呼ぶ形にすると、だれが選ばれるかが運になり、遊びとして安心して続けられます。', '1回ごとに指名の条件（色・持ち物・誕生月など）を先生が指定すると、相談が短くなりテンポよく進みます。', '特定の子が続けて指名されそうなときは、先生が「今の条件は1回で終わり」と切り替えます。名前での指名や、外見をからかう言い方は始める前に禁止と伝えておきます。', '手をつなぐのが苦手な子は、となりの人と肩をならべて立つだけでよいことにします。', null, 13),
  ('don-janken', 'どんじゃんけん', '✊', 'team-line', 'そとあそび・体育館（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会']::text[], '15〜20分', 'ラインやフープを並べる（5分）', '体育館・校庭', array['体育館', '校庭']::text[], 'クラス全体（2チーム）', 'ライン（体育館のラインやフープでも可）', array['1本の線（またはフープを並べたコース）の両端に、2チームが1列に並ぶ。', '合図で両チームの先頭が線の上を進み、出会ったところで「どーん！じゃんけんぽん」と勝負する。', '勝った人はそのまま進み、負けた人は列の後ろへ。負けたチームは次の人がすぐスタートする。', '相手のスタートの線までたどりつけたら1点。決めた時間の中で、点数が多いチームの勝ち。']::text[], 'じゃんけんで決まるので、走るのが苦手な子も対等に活躍できます。応援の声が自然に出るレクです。', '5・6年でやるときは、はじめから「へびじゃんけん（うずまきの線を引いて同じことをする）」にするか、進み方をけんけん・スキップ・後ろ向きと毎回変えてください。まっすぐな線のままだと、高学年には物足りません。', '出会い頭の勢いがつきすぎないよう、「出会う直前は止まってからじゃんけん」と決めておきます。', null, null, 14),
  ('janken-train', 'じゃんけん列車', '🚃', 'gym-circle', 'そとあそび・体育館（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会', '学級開き', '雨の日']::text[], '10〜15分', '机を下げる（5分）', '体育館・教室（机を下げて）', array['体育館', '教室']::text[], 'クラス全体', 'なし（あれば音楽）', array['音楽が鳴っている間、全員が自由に歩き回る。', '音楽が止まったら、近くの人とじゃんけんをする。相手が見つからない人は、先生のところへ来る。', '負けた人は勝った人の肩に手を置いて後ろにつながる。列の先頭同士が次のじゃんけんをする。', '最後は1本の長い列になり、先頭の人がチャンピオン。']::text[], '最後は全員がつながるので、「勝っても負けても最後は1つの列」という気持ちのよい終わり方になります。', '音楽がないときは、先生の「ストップ！」の声でも同じように進められます。', '列が長くなると急には止まれません。「走らない・歩くだけ」を最初に約束します。', '肩にさわられるのが苦手な子は、すぐ後ろを歩くだけ、またはタオルの端を持ってつながる形でもよいことにします。高学年で男女が続いて気まずそうなときは、先生がさりげなく列に入って間をつなぎます。', null, 15),
  ('dodgeball', 'ドッジボール（やさしいルール）', '🤾', 'ball', 'そとあそび・体育館（体を動かす系）', array['中学年', '高学年']::text[], array['お楽しみ会']::text[], '20〜30分', 'コート・ボールの用意（体育館のラインを使えば3分／校庭にラインを引くなら10分）', '体育館・校庭（ドッジボールコート）', array['体育館', '校庭']::text[], 'クラス全体（2チーム）', 'やわらかいボール1個、ビブス', array['2チームに分かれ、内野と外野に入る。ボールはやわらかいものを使う。', '相手の内野の人にボールを当てたら、当たった人は外野へ。外野の人が当てたら内野に戻れる。', '顔をねらうのは反則。顔に当たったときは、当たった人は外野に出ない（ノーカウント）。', '制限時間で内野の人数が多いチームの勝ち。']::text[], '得意な子にボールが集中しがちです。「投げる前に1回はパスをする」ルールにすると、全員がボールにさわれます。', '当たるのが苦手な子には「外野専門」で参加してもらうのも一つ。逃げるだけの時間が減り、最後まで役割が残ります。', 'やわらかいボールを使い、「顔をねらわない」「至近距離で強く投げない」を必ず先に確認します。当たって痛かったときは、すぐ止めて全員で確認する時間をとります。暑い時期は、とちゅうで一度止めて水分をとる時間をつくります。暑さ指数が高い日は、時間を短くするか日かげでできる遊びに変えてください。体育館は思った以上に暑くなるので、窓を開けてから始めます。', null, null, 16),
  ('king-dodgeball', '王様ドッジボール', '👑', 'ball', 'そとあそび・体育館（体を動かす系）', array['中学年', '高学年']::text[], array['お楽しみ会']::text[], '20〜30分', 'コート・ビブス・くじの用意（体育館のラインを使えば5分／校庭は10分）', '体育館・校庭（ドッジボールコート）', array['体育館', '校庭']::text[], 'クラス全体（2チーム）', 'やわらかいボール1〜2個、ビブス、王様を決めるくじ', array['2チームに分かれる。王様は先生が引いたくじで決め、本人にだけそっと伝える（チームの中で決めない）。', 'ふつうのドッジボールと同じように始める。当たった人は外野に出る。', '王様が当たったら、その回はそこで終わり。だれが王様だったかは発表せず、すぐ次のくじを引く。', '1回戦が終わったら王様を引き直して、もう一度行う。']::text[], '王様をチームで決めると押しつけ合いになり、負けたときに「あの子のせい」になりがちです。くじで決めて本人だけが知っている形にすると、その空気が生まれません。', '全員が「自分が王様かもしれない」と思って動くので、逃げ方にも作戦が生まれます。', 'やわらかいボールを使い、「顔をねらわない」「顔に当たったら当たっていないことにする」を確認します。王様を探して人が1か所に集まりやすいので、ぶつからないよう声をかけます。暑い時期は、とちゅうで一度止めて水分をとる時間をつくります。暑さ指数が高い日は、時間を短くするか日かげでできる遊びに変えてください。', null, null, 17),
  ('rolling-dodgeball', '転がしドッジボール', '⚽', 'ball', 'そとあそび・体育館（体を動かす系）', array['低学年', '中学年']::text[], array[]::text[], '15〜20分', 'ボールの用意（3分）', '体育館・校庭', array['体育館', '校庭']::text[], 'クラス全体', 'やわらかいボール1〜2個', array['コートの外側を囲むように守り（外野）が立ち、中に逃げる人が入る。', '外野はボールを投げずに、必ず転がして中の人の足にあてる。', '足に当たった人は外に出て、外野になる。', '最後まで残った人が勝ち。時間で区切って何回か行う。']::text[], '投げないので当たっても痛くなく、ボールが苦手な子や低学年でも安心して参加できます。', 'ボールを2個にすると、一気にスリルが増します。', '「ボールは必ず床を転がす（浮かせない）」ことを、始める前に実演して確認します。', null, null, 18),
  ('naka-ate', '中当て（円形ドッジ）', '🎯', 'ball', 'そとあそび・体育館（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array[]::text[], '15〜20分', 'ボールの用意（3分）', '体育館・校庭', array['体育館', '校庭']::text[], 'クラス全体', 'やわらかいボール1個', array['大きな円を作り、半分の人が円の外側（外野）、半分が中（内野）に入る。', '外野はボールをパスしながら、中の人をねらって当てる（1・2年生とやるときは、投げずに転がして足に当てる）。', '当たった人は外に出て、当てた人と入れかわって内野に入る。', '時間を決めて行い、最後に内野に残っていた人を紹介する。']::text[], 'コートを引かなくても円を作るだけで始められるので、余った10分にも向いています。', '外野がパスを3回つないでから投げるルールにすると、全員がボールにさわれます。', '首から上はねらわないこと、当たってしまったときは「当たっていないこと」にするのを、先に決めておきます。', null, null, 19),
  ('long-rope', '大なわ8の字跳び', '🪢', 'rope', 'そとあそび・体育館（体を動かす系）', array['中学年', '高学年']::text[], array['学期末']::text[], '15〜20分', '長なわの出し入れ（5分）', '体育館・校庭', array['体育館', '校庭']::text[], 'クラス全体（1〜3チーム）', '長なわ', array['2人が回し手になり、なわを一定のリズムで回す。', '跳ぶ人は一方から入って1回跳び、反対側へ抜けて列の後ろに戻る（8の字の動き）。', '3分間で何回跳べたかを数える。', '回数を記録しておき、次に挑戦したときと比べる。']::text[], '苦手な子には、先生が横で「はい」と入るタイミングの声をかけます。それでも入れないときは、手をつないで一緒に入ると跳べるようになります（背中を押すのは転倒につながるので避けます）。', '「引っかかってもカウントを止めない」ルールにすると、責める空気が生まれにくくなります。学年末は「クラスで跳んだ最後の記録」として黒板に残すと、記録づくりが思い出になります。', 'なわを回す2人は同じ速さで回すこと、列は跳ぶ人の進む向きにそって並ぶことを確認します。', 'なわを回す係・数える係・入るタイミングの声かけ係を交代でまわし、全員がどこかの役につくようにします。跳ばずに、回るなわをくぐり抜けるだけでもカウントします。', null, 20),
  ('oonami-konami', '大波小波', '🌊', 'rope', 'そとあそび・体育館（体を動かす系）', array['低学年', '中学年']::text[], array[]::text[], '10〜15分', '長なわの出し入れ（5分）', '体育館・校庭', array['体育館', '校庭']::text[], '10人程度のグループ', '長なわ', array['2人がなわを持つ役になり、まずはなわを回さずに左右に揺らす（大波小波）。1・2年生とやるときは、なわを持つ役は先生か高学年が担当する。', '「大波小波でグルッと回って……」と声をかけながら、揺れているなわを1人ずつ跳び越える。', '慣れてきたら、そのまま回すなわに切りかえる。回すなわでは「郵便屋さん」など、なわとび歌に合わせると全員のリズムがそろう。', '何人連続で跳べたかを数えて記録する。']::text[], '回すなわが怖い子も、揺れるなわなら跳べます。8の字跳びの前の練習としても使えます。クラス全体でやるときは、なわを2〜3本出して同時に回すと、待ち時間がぐっと減ります。', null, 'なわが顔に当たらないよう、なわを持つ2人は腰から下の高さで揺らすようにします。', null, null, 21),
  ('shuttle-relay', '折り返しリレー', '🏃', 'relay', 'そとあそび・体育館（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会']::text[], '15〜20分', 'コーンとバトンを置く（5分）', '体育館・校庭', array['体育館', '校庭']::text[], 'クラス全体（3〜4チーム）', 'コーン、バトン（なければタスキ）', array['チームごとに1列に並び、20〜25m先にコーンを置く。低学年は待っているうちに列がくずれるので、並ぶ場所にフープや線で印をつけておく。', '合図で先頭が走り、コーンを回って戻り、次の人にバトンを渡す。', '全員が走り終わったチームから座る。', '2回戦は、走る順番をチームで相談して変えてよいことにすると作戦が生まれる。']::text[], '走る距離を短めにして回数を増やすと、足の速さの差が目立ちにくくなります。チーム数を増やして同時に走らせると、待っている時間が短くなり、集中が切れません。', '「スキップで」「ボールを運んで」など走り方を指定すると、毎回結果が変わって盛り上がります。走らず歩くコースを1つ用意し、どのチームも1人はそこを使ってよいことにすると、全員が出られます。', 'コーンを回るときにふくらむと隣のコースとぶつかります。コースの間隔を広めにとります。', null, null, 22),
  ('typhoon-eye', '台風の目', '🌀', 'relay', 'そとあそび・体育館（体を動かす系）', array['中学年', '高学年']::text[], array['お楽しみ会', '学期末']::text[], '15〜20分', '棒とコーンの用意（5分）', '校庭・体育館', array['校庭', '体育館']::text[], 'クラス全体（3〜4チーム）', '長い棒（1チーム1本）、コーン', array['3〜4人で1組になり、1本の棒を横に持って並ぶ。', '合図で走り出し、コーンを回って戻ってくる。棒を離してはいけない。', '戻ったら、待っている人たちの足元を棒でくぐらせ、次に頭の上を通して、次の組に渡す。', '全員が走り終わったチームの勝ち。']::text[], 'コーンを回るとき、内側の人はその場で回り、外側の人は大きく走るのがコツ。作戦タイムを取ると記録が伸びます。', null, '棒が顔に当たらないよう、足元をくぐらせるときは低く、頭の上を通すときは高く、と声をかけます。長い棒を持ったまま走るので、チームごとのコースは3mほど間をあけます。暑い時期は、とちゅうで一度止めて水分をとる時間をつくります。暑さ指数が高い日は、時間を短くするか日かげでできる遊びに変えてください。', '走るのがむずかしい子がいるチームは、コーンまでの距離を短くした「歩くコース」を使ってよいことにします。', null, 23),
  ('tamaire', '玉入れ', '🔴', 'field', 'そとあそび・体育館（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会']::text[], '10〜15分', '玉とかごの準備・片づけ（10分）', '校庭・体育館', array['校庭', '体育館']::text[], 'クラス全体（2チーム）', '玉入れの玉（新聞紙を丸めたものでも可）、かご', array['チームごとにかごを置き、まわりに円を作って立つ。', '合図で1分間、玉を投げ入れる。', '終わったら全員で声をそろえて数を数える。', '2回戦は、円を少し広げる・いつも使わないほうの手で投げるなど、条件を変えて行う。']::text[], '数えるところまでが楽しみの一つ。「いち、にー」と全員の声をそろえると一体感が出ます。', '新聞紙を丸めて玉を作るところからやると、図工の時間とつながる学級レクになります。5・6年でやるときは「いつも使わないほうの手だけ」「かごから5歩下がって」などのハンデ戦にすると、学期末の箸休めとして盛り上がります。', 'かごのすぐ下に人が入らないよう、投げる位置の線を引いておきます。', null, null, 24),
  ('paper-plane', '紙ひこうきとばし大会', '✈️', 'field', 'そとあそび・体育館（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会', '学期末']::text[], '20〜30分', '紙を1人2枚ずつ配る（5分）', '体育館・校庭（風のない日）', array['体育館', '校庭']::text[], 'クラス全体', '紙（1人2枚。広告やコピー用紙の裏でよい）', array['1人2枚の紙で、紙ひこうきを折る（折り方は自由。10分ほど時間をとる）。', '全員が同じ向きに並び、投げる線を決める。', '合図で一斉にとばす。いちばん遠くまでとんだ紙ひこうき、いちばん長く飛んでいた紙ひこうきなどを表彰する。', '拾いに行くのは、全員が投げ終わってからにする。']::text[], '「いちばん遠くまで賞」「長くとんでいたで賞」「まっすぐとんだで賞」「かっこいいで賞」のように賞をいくつか用意すると、いろいろな子が主役になれます。', '作る時間を授業の終わりにとっておき、飛ばすのは次の日の学活にすると、1コマに収まります。卒業前や学年末にやるときは、飛ばす前に羽根へクラスへの一言を書いてもらうと、勝ち負けより思い出が残ります。', '先端がとがった折り方をした子には、先を1cmほど折り返すよう伝えます。投げる方向に人がいないことを必ず確認します。', null, null, 25),
  ('handkerchief-drop', 'ハンカチ落とし', '🧣', 'seated-circle', '室内レク（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会', '雨の日']::text[], '15〜20分', '机を下げて円をつくる（5分）', '教室（机を下げて円に）・多目的室', array['教室']::text[], 'クラス全体', 'ハンカチ（またはタオル）', array['全員が外側を向いて円になって座り、鬼を1人決める。', '鬼はハンカチを持って円の外側を歩き、気づかれないように誰かの後ろにそっと落とす。', '落とされたことに気づいた人はハンカチを拾って鬼を追いかける。鬼が空いた場所に座れれば成功、タッチされたらもう一度鬼をする。', '気づかないまま一周されたら、その人が次の鬼になる。']::text[], '「1人1回は鬼をやる」と決めたくなりますが、35人だと20分では回りません。「時間内にできた人まで。続きは次回」と先に伝えておくと、あわてずに終われます。', 'ハンカチを2枚にすると、テンポが速くなり高学年でも盛り上がります。5・6年でやるなら、チーム対抗で「何周逃げ切れたか」を得点にすると、遊びではなく種目として成立します。', '走る通り道に机やランドセルが出ていないか、始める前に確認します。', '走って追いかけるのがむずかしい子がいるときは、「歩いて一周先に戻れたら成功」のルールにします。', 'handkerchief-drop', 26),
  ('nandemo-basket', 'なんでもバスケット', '🪑', 'seated-circle', '室内レク（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会', '学級開き', '雨の日']::text[], '15〜20分', '机を下げて椅子を円に並べる（5分）', '教室（机を下げて）', array['教室']::text[], 'クラス全体', '人数分より1つ少ない椅子', array['椅子を円に並べて座り、鬼を1人決める（椅子は鬼の分だけ少なくする）。', '鬼が「〇〇な人！」とお題を言い、当てはまる人は立って別の椅子に移動する。', '座れなかった人が次の鬼になり、新しいお題を出す。', '「なんでもバスケット」と言ったら全員が移動する。']::text[], 'お題は見た目のことより「朝ごはんを食べてきた人」のような行動にすると、外見の話題になりません。', '何度も鬼になってしまう子がいたら、「2回目の人は先生と一緒にお題を考える」とフォローします。', '移動は「歩く」こと、隣の椅子には座らないことをルールにすると、ぶつかりません。椅子の向きは変えない、と先に伝えておくと（低学年はくるくる回してしまいます）、ぶつかりが減ります。', 'お題を声で言うのがむずかしい子のために、お題カードを10枚ほど用意しておき、引いて見せるだけでもよいことにします。', 'safe-fruits-basket', 27),
  ('musical-chairs', 'いす取りゲーム（全員参加版）', '🎵', 'seated-circle', '室内レク（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会', '学級開き', '雨の日']::text[], '15〜20分', '椅子を円に並べる・音楽の用意（5分）', '教室（机を下げて）・多目的室', array['教室']::text[], 'クラス全体', '椅子、音楽（タブレットなどで可）', array['椅子を外向きの円に並べる。椅子の数は人数より1つ少なくする。', '音楽が鳴っている間は椅子のまわりを歩き、止まったら座る。', '座れなかった人は、次の回で音楽を止める係になり、次の合図を出す。椅子は減らさないので、全員が最後まで参加できる。', '5〜6回くり返し、最後に「1度も座れなかった人」がいないかを確認して終わる。']::text[], '椅子を減らしていく従来のやり方は、早く抜けた子の待ち時間が長く、椅子ごと倒れる事故も起きやすい遊びです。減らさない形にすると、盛り上がりはそのままで最後まで全員が動けます。', '人数が多いときは、2つの円に分けて同時に行うと待ち時間がさらに減ります。体育館でやる場合は、椅子を運んで並べて片づけるまでに10分以上かかることを見込んでください。5・6年では「音楽を止める係」「実況係」を子どもに任せると、椅子取りそのものより役割のほうが盛り上がります。', '「先に座っていた人の勝ち」「引っぱらない」を先に確認します。椅子は背もたれが外を向くように置くと、倒れにくくなります。', null, null, 28),
  ('balloon-volley', '風船バレー', '🎈', 'team-line', '室内レク（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会', '雨の日']::text[], '15〜20分', '風船をふくらませる（10分）', '教室（机を下げて）・多目的室・体育館', array['教室', '体育館']::text[], 'クラス全体（2チーム）', '風船（予備を数個）', array['2チームに分かれ、間にひも（またはライン）を引いて向かい合う。', '風船を落とさないように打ち合い、相手コートの床に落ちたら1点。', '「全員が1回さわってから返す」ルールにすると、全員が風船にさわれる。', '先に10点取ったチームの勝ち。']::text[], '風船はゆっくり落ちるので、運動が苦手な子も無理なく参加できます。雨の日の体育の代わりにもなります。', '座ったまま行う「おすわり風船バレー」にすると、教室でも安全に遊べます。', 'ゴム（ラテックス）アレルギーの子がいないか、事前に確認します。割れた破片は口に入ると危険なので、その場ですぐ集めて捨てます。風船は、子どもがいない場所でふくらませておきます。', '破裂音が苦手な子には、イヤーマフや耳せんを使ってよいことを先に伝えます。少し小さめにふくらませると音も小さくなります。', null, 29),
  ('newspaper-island', '新聞紙じゃんけん', '📰', 'team-line', '室内レク（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会', '雨の日']::text[], '10〜15分', '新聞紙を1人1枚配る（5分）', '教室（机を下げて）', array['教室']::text[], 'ペア〜クラス全体', '新聞紙（1人1枚）', array['1人1枚の新聞紙を広げ、その上に立つ。', '近くの人とじゃんけんをする。', '負けた人は新聞紙を半分に折り、小さくなった紙の上に立つ。', '新聞紙から足がはみ出したら終わり。終わった人は審判役になり、残っている人の足元を見てあげる。最後まで立っていられた人が勝ち。']::text[], '小さくなってくると、片足立ちやつま先立ちで工夫する子が出てきます。その様子を実況すると盛り上がります。', 'ペアで1枚の新聞紙に2人で乗るルールにすると、協力して支え合う遊びになります。', 'ふらついて倒れたときにぶつからないよう、新聞紙どうしの間隔を広くとります。', '立ってバランスをとるのがむずかしい子は、いすに座って新聞紙の上に両足をのせる形でもできます。ふらついたら手をついてよいことにします。', null, 30),
  ('janken-pyramid', 'じゃんけんピラミッド', '🔺', 'team-line', '室内レク（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array['学級開き', '雨の日']::text[], '10〜15分', '机を下げる（5分）', '教室・体育館', array['教室', '体育館']::text[], 'クラス全体', 'なし', array['「関所（かんしょ）」＝通るために勝たないといけない場所を、階段のように3つ作る（1つ目は5人、2つ目は3人、3つ目は先生）。関所の人は先生が指名する。', 'ほかの全員が1つ目の関所の人とじゃんけんをし、勝ったら2つ目へ進む。負けたらもう一度1つ目に挑戦する。', '3つ目（先生）に勝てたらクリア。クリアした人は黒板に「正」の字を1画ずつ書き足し、そのあとは1つ目の関所に加わって挑戦者を待つ。', 'タイマーが鳴ったら、クラス全体で何人クリアできたかを記録として残す。']::text[], '負けても何度でも挑戦できるので、勝ち負けが苦手な子でも最後まで参加できます。最後の関所を先生1人にすると行列ができるので、3つ目の関所にはクリアした人にも2〜3人入ってもらうと、35人でも15分で回ります。', '関所ごとに「あっち向いてホイ」「後出しじゃんけん」など勝負の内容を変えると飽きません。高学年は、この「勝負の内容を変える」形にすると手ごたえが出ます。', '関所の前は1列に並び、前の人を押さないことを先に約束します。', '黒板には名前ではなく「正」の字だけを書きます。クリアできていない子が分かってしまわないようにするためです。1・2年生とやるときは、クリアした人は関所に回らず、そのまま座って応援する形にすると混乱しません。', null, 31),
  ('lion-hunt', '猛獣狩りに行こうよ', '🦁', 'gym-circle', '室内レク（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array['学級開き', 'お楽しみ会', '雨の日']::text[], '10〜15分', '机を下げる（5分）', '教室（机を下げて）・体育館', array['教室', '体育館']::text[], 'クラス全体', 'なし', array['先生の「猛獣狩りに行こうよ！」の掛け声を、全員が身ぶりつきでまねする。', '先生が動物の名前（例：ライオン＝4文字）を言う。低学年や1回目は「ライオン、4人！」と人数も一緒に言う。', 'その文字数と同じ人数のグループをすばやく作って座る。', 'グループができたら、そのメンバーで簡単なお題（好きな給食など）を話してから次へ進む。']::text[], 'グループに入れない子が出たときは、先生が「先生も入れて！」と一緒に入ると、気まずさが残りません。2回目からは「〇人グループ」と書いたカードを見せてから合図すると、あわてずに組めます。', 'できたグループで自己紹介や一言トークをはさむと、班づくりのきっかけにもなります。', 'あわてて人を引っぱると転びます。「さそうのは言葉で、手は引っぱらない」を先に約束しておきます。', '毎回あぶれてしまう子がいるときは、先生がその子と組んでから人数を数え始めます。', 'lion-hunt', 32),
  ('bomb-game', 'バクダンゲーム', '💣', 'seated-circle', '室内レク（体を動かす系）', array['低学年', '中学年']::text[], array['雨の日']::text[], '10〜15分', 'ボールと音楽の用意（3分）', '教室', array['教室']::text[], 'クラス全体・グループ', '小さなボールやお手玉（バクダン役）、音楽', array['円になって座り、バクダン役のボールを1つ用意する。', '音楽が鳴っている間、ボールを隣の人へどんどん回す。', '音楽が止まったとき、ボールを持っていた人が「バクダン」。お題（好きな食べ物など）に答える。', '答えたら、また音楽を再開する。']::text[], '当たった人が「罰ゲーム」ではなく「発表のチャンス」になるよう、お題はやさしいものにします。', 'ボールを2個にして反対回りで同時に回すと、難しさとスリルが増します。', '投げて渡すと落として取り合いになります。「必ず手渡し」を先に伝えておきます。', 'お題に声で答えるのがむずかしい子のために、絵カードを数枚用意しておき、1枚えらんで見せる形でもよいことにします。', null, 33),
  ('ball-pass-relay', 'ボール送りリレー', '🏐', 'team-line', '室内レク（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array['雨の日']::text[], '10〜15分', 'ボールを列の数だけ用意（3分）', '教室（列のまま）・体育館', array['教室', '体育館']::text[], 'クラス全体（列・班ごと）', 'ボール（列の数だけ）', array['班や座席の列ごとに1列に並び、先頭にボールを渡す。', '合図で、頭の上を通して後ろへ送る。最後の人まで届いたら、今度は足元を通して前に戻す。', '先頭に戻ったチームから「はい！」と手をあげる。', '2回戦は「体の横をひねって渡す」など、渡し方を変える。']::text[], '座ったままでもできるので、教室の座席のまますぐに始められます。', 'ボールを風船やぬいぐるみに変えると、低学年でも扱いやすくなります。', '落ちたボールを追いかけて席を立つとぶつかります。「落ちたら拾うのは近くの1人だけ」と決めておきます。', null, null, 34),
  ('gesture-relay', 'ジェスチャー伝言リレー', '🎭', 'team-line', '室内レク（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会', '学期末', '雨の日']::text[], '15〜20分', 'お題カードを書く（10分）', '教室・多目的室', array['教室']::text[], 'クラス全体（4〜6人のチーム）', 'お題を書いたカード', array['チームごとに1列に並び、全員が前を向く（いちばん後ろの人だけが先生のお題カードを見る）。', '後ろの人が前の人の肩をたたき、振り向いたらジェスチャーだけでお題を伝える。声は出さない。', '同じように前へ前へと伝えていき、先頭の人が答えを言う。', '正解したチームに得点。お題を変えて何回戦か行う。']::text[], 'お題は「なわとび」「そうじ」など動きのあるものにすると伝わりやすく、失敗も笑いに変わります。1・2年生とやるときは「ぞう」「ねこ」「はみがき」など、体ひとつで表せるものだけにします。', 'どこまで正しく伝わっていたかを1人ずつ見せてもらうと、大いに盛り上がります。', '肩をたたく強さは、実際に先生がやって見せておきます。体をつかんで向きを変えるのは禁止にします。', null, 'telephone-game', 35),
  ('finger-game', 'いっせーのーせ（指スマ）', '👍', 'desk-group', '室内レク（静かに楽しむ系）', array['低学年', '中学年', '高学年']::text[], array['雨の日']::text[], '5〜10分', 'なし', '教室（席のまま）', array['教室']::text[], '4〜6人のグループ', 'なし', array['4〜6人で輪になり、全員が両手のこぶしを前に出す（1・2年生は4人までにすると分かりやすい）。', '順番に1人が「いっせーのーせ、2！」のように数を言いながら、自分の親指を立てる（0〜人数×2の間で言う）。', '同時に立った親指の合計が、言った数とぴったり合っていたら、言った人は片手を下げられる。', '両手を先に下げられた人が勝ち。']::text[], '道具も場所も要らず、席についたまま2〜3分で1ゲーム終わります。指の数をたし算するので、1年生とやるのは数のたし算に慣れてくる2学期以降がおすすめです。', 'グループを4人までにすると、数の読み合いがやさしくなり低学年でも楽しめます。', null, null, null, 36),
  ('bingo', 'ビンゴ大会', '🎱', 'quiz', '室内レク（静かに楽しむ系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会', '学期末', '雨の日']::text[], '20〜30分', 'カードと数字くじの用意（10分）', '教室', array['教室']::text[], 'クラス全体', 'ビンゴカード（マスを自分で書いてもよい）、数字のくじ', array['マスを書き、数字を自由に入れる。3×3のマスなら1〜25、5×5のマスなら1〜75の中から選んで書く（マスの数より書ける数字がずっと多いことが大事）。', '先生がくじを引いて数字を読み上げる。持っていたら、そのマスに印をつける。', 'たて・よこ・ななめが1列そろったら「ビンゴ！」。', '全員がビンゴになるまで続け、早かった人から賞状やシールなどを渡す。']::text[], 'マスの数と同じ範囲の数字（5×5に1〜25など）にすると全員が同時にそろってしまいます。範囲は必ずマスの数の3倍程度にしてください。', '数字のかわりに「クラスの人の名前」「好きな給食メニュー」を書く『クラスビンゴ』にすると、お楽しみ会にぴったりです。3×3にすれば10分程度で終わります。', null, '1・2年生には、数字を印刷したカードを先生が配ります。そろった人から前に取りに来る形にし、順位は読み上げません。低学年は数字を探すだけで時間がかかるので、3×3のマスにして30分をみておきます。', 'word-bingo', 37),
  ('maru-batsu-quiz', '○×クイズ大会', '⭕', 'quiz', '室内レク（静かに楽しむ系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会', '学期末', '雨の日']::text[], '15〜20分', '問題を10問ほど用意（10分）', '教室・体育館', array['教室', '体育館']::text[], 'クラス全体', 'なし（あれば○×のカード）', array['問題を聞いて、○だと思う人は手で丸、×だと思う人はバツを頭の上で作る。', '先生が正解を発表する。当たった人は手元の紙に「正」の字を書き足していく。まちがえても、そのまま次の問題に参加できる。', '10問終わったところで、いくつ当たったかを聞き、多かった人に拍手を送る。', 'クイズは「この学校の階段は何段？」など、身近な話題にすると盛り上がる。']::text[], '子どもに問題を作ってもらうと、そのまま次のレクの準備になります。作ったクイズはためておくと便利です。', '体育館なら、○と×の場所を決めて移動する形にすると盛り上がります（移動は走らず歩く、と先に約束します）。「まちがえたら座る」勝ち抜き戦もできますが、早く外れた子の待ち時間が長くなるので、問題数を5問ほどに減らしてください。', null, null, 'maru-batsu-game', 38),
  ('takenoko-nyokki', 'たけのこニョッキ', '🎋', 'seated-circle', '室内レク（静かに楽しむ系）', array['低学年', '中学年', '高学年']::text[], array['雨の日']::text[], '10分程度', 'なし', '教室', array['教室']::text[], '5〜10人のグループ', 'なし', array['グループで「たけのこ、たけのこ、ニョッキッキ！」と声をそろえて言う。', 'そのあと、順番を決めずに「1ニョッキ！」「2ニョッキ！」と数字を言いながら、手を合わせて上にあげる。', '同時に同じ数字を言ってしまった人、最後まで残ってしまった人が負け。', 'グループを変えて何回か行う。']::text[], '人数が多いと当たりが分かりにくいので、5〜8人くらいのグループに分けるとテンポよく進みます。', '負けた人にお題（好きな教科を言う）を出すと、自然に発表の機会が生まれます。', null, 'お題に答えるとき、声に出すのがむずかしい子は、指さしたり首をふったりで答えてもよいことにします。', null, 39),
  ('ng-word', 'NGワードゲーム', '🙊', 'desk-group', '室内レク（静かに楽しむ系）', array['中学年', '高学年']::text[], array['お楽しみ会', '学期末', '雨の日']::text[], '15〜20分', '先生がNGワードのカードを用意（10分）', '教室', array['教室']::text[], '4〜6人のグループ', '先生が用意したNGワードのカード（人数分）', array['先生が用意したカードを、1人1枚、文字が見えないように机に伏せて置く（自分のカードは見ない）。', '合図で、自分以外の人のカードだけをのぞいて内容を確かめ、またもとに戻す。', 'グループで自由に会話をする。テーマは「今日の給食」「休み時間の話」など決めておく。', '自分のNGワードを言ってしまったらアウト。最後まで言わずに残った人が勝ち。']::text[], 'NGワードは「うん」「先生」「たぶん」など、会話でつい出る言葉にすると盛り上がります。子どもに作らせると、あだ名や見た目の言葉が混ざることがあるので、必ず先生が用意してください。', '紙を背中に貼る方法もありますが、机に伏せて置くほうが、人の体にさわらずに済み、はがれる心配もありません。', '人の名前・見た目・苦手なことをNGワードにしない、と最初に全員へ伝えます。', '話す量は勝負に関係ありません。最後まで自分のNGワードを言わなかった人は、全員を勝ちにします。', null, 40),
  ('magical-banana', 'マジカルバナナ', '🎤', 'seated-circle', '室内レク（静かに楽しむ系）', array['低学年', '中学年', '高学年']::text[], array['雨の日']::text[], '10分程度', 'なし', '教室', array['教室']::text[], 'グループ〜クラス全体', 'なし', array['手びょうしでリズムを取りながら「マジカルバナナ、バナナといったら黄色」のように連想をつなげる。', '次の人は「黄色といったらレモン」と、前の人の言葉から連想した言葉を言う。', 'リズムにおくれた人、前に出た言葉を言ってしまった人が負け。言葉が出ないときは「パス」と言って手をたたけば、次の人につなげられる。', 'テンポを少しずつ速くしていくと、さらに盛り上がる。']::text[], '最初はゆっくりのリズムで練習してから始めると、低学年でもつながります。', '「国語の言葉」「都道府県」などジャンルを決めると、そのまま学習の復習になります。', null, null, null, 41),
  ('acchi-muite-hoi', 'あっち向いてホイ・トーナメント', '👉', 'team-line', '室内レク（静かに楽しむ系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会', '雨の日']::text[], '15〜20分', '黒板にトーナメント表を書く（5分）', '教室', array['教室']::text[], 'クラス全体', 'かち上がりの表（黒板に書く）', array['黒板に「かち上がりの表」（勝った人が上に進んでいく表）を書き、対戦相手を決める。', 'じゃんけんで勝った人が指をさし、負けた人が顔を向ける「あっち向いてホイ」で勝負する。', '勝った人は次の回戦へ。負けた人は「まけたグループ」の表に移り、負けた人どうしでもう一度対戦する。', 'どちらの表も最後まで進め、「チャンピオン」と「まけたグループのチャンピオン」の2人を全員の前で決める。']::text[], 'トーナメント表を黒板に残しておくと、休み時間にも子どもたちだけで続きを楽しめます。', '人数が多いときは班対抗の勝ち抜き戦にすると、短い時間で終わります。', '顔の近くを指さす遊びです。「目を指さない」「顔にさわらない」を先に確認します。', null, null, 42),
  ('ten-seconds', '10秒ぴったりチャレンジ', '⏱', 'quiz', '室内レク（静かに楽しむ系）', array['低学年', '中学年', '高学年']::text[], array['雨の日']::text[], '5〜10分', 'ストップウォッチの用意（1分）', '教室', array['教室']::text[], 'クラス全体', 'ストップウォッチ（タブレットのタイマーでも可）', array['全員が目を閉じ、先生の「スタート」の合図で心の中で10秒を数える。', '10秒たったと思ったら、静かに手をあげる（または立つ）。', '先生は実際の時間を見て、10秒にいちばん近かった人を発表する。', '2回戦は「15秒」など、時間を変えて行う。']::text[], '静かに終われるレクなので、お楽しみ会の最後や、次の授業に入る前の切りかえに向いています。', '班対抗にして、班の合計の誤差が少ないチームの勝ちにすると、協力する場面が生まれます。', null, '目を閉じるのが苦手な子は、机の上の一点を見つめるだけでもかまいません。', null, 43),
  ('box-guess', '箱の中身はなんだろな', '📦', 'quiz', '室内レク（静かに楽しむ系）', array['低学年', '中学年']::text[], array['お楽しみ会', '雨の日']::text[], '15〜20分', '箱と中身の用意（10分）', '教室', array['教室']::text[], 'クラス全体', '中の見えない箱、中に入れる物（文具・ぬいぐるみ・スポンジなど）', array['見えないように、箱に物を1つ入れておく。', '代表の子が手を入れて、さわった感じを言葉で説明する（「つるつるしている」など）。', 'まわりの子はヒントを聞いて、何が入っているかを当てる。', '正解を発表し、次の子と交代する。']::text[], '説明する力を使うレクなので、国語の「話す・聞く」の学習ともつなげられます。', 'さわった人は声を出さず、ジェスチャーだけで伝えるルールにすると難しさが上がります。', 'とがった物・こわれる物・食べ物・生き物は入れません（けが・アレルギー・衛生のため）。', 'さわるのが苦手な子は、先に中身を見せてもらってヒントを出す「出題する側」で参加します。', null, 44),
  ('treasure-hunt', '教室宝さがし', '🔎', 'quiz', '室内レク（静かに楽しむ系）', array['低学年', '中学年']::text[], array['お楽しみ会', '雨の日']::text[], '15〜20分', 'カードを教室に隠す（5分）', '教室', array['教室']::text[], 'クラス全体（班ごと）', '番号を書いたカード（人数の2倍くらい）', array['休み時間のうちに、番号を書いたカードを教室のあちこちに隠しておく（人の机の中・ロッカーの私物の中には入れない）。', '合図で探し始める。見つけたカードは班のかごに入れ、入れたら自分の席にもどって座る（そのまま探し続けない）。', 'タイマーが鳴ったら、班ごとにカードの番号を合計して得点にする。', '最後に、見つからなかったカードを先生が示して種明かしをする。']::text[], 'カードの点数に差をつけておく（1点〜10点）と、枚数が少ない班にも逆転の可能性が残ります。', 'カードに「好きな給食を発表」などのミッションを書いておくと、探したあとにもう一度盛り上がります。', '高い場所・掃除用具入れの中・電気まわりには隠さないこと、走らないことを先に伝えます。', null, 'treasure-hunter', 45),
  ('card-games', 'トランプ大会（ばば抜き・七ならべ）', '🃏', 'desk-group', '室内レク（静かに楽しむ系）', array['低学年', '中学年', '高学年']::text[], array['学期末', '雨の日']::text[], '20〜30分', 'トランプを班の数だけ用意（3分）', '教室', array['教室']::text[], '4〜6人のグループ', 'トランプ（グループの数だけ）', array['グループごとに机を合わせ、トランプを配る。', '最初の10分は「ばば抜き」、次の10分は「七ならべ」など、やることを先に決めておく。', '終わったら、勝った人や楽しかった場面をグループごとに発表する。', 'カードの枚数を確認してから片づける。']::text[], '雨の日の休み時間や、学期末のお楽しみ会の1コーナーとして定番です。遊び方を知らない子がいる前提で、最初に全体でルールを確認します。1・2年生とやるときは、七ならべを入れずに「ばば抜き」だけにします。', '神経衰弱にすると声が少なく静かに進むので、隣のクラスが授業中のときでも安心です。', null, 'ばば抜きは、最後の1人が決まった時点で終わりにします。順位は言わず、「おつかれさま」で片づけます。', 'memory-match', 46),
  ('association-game', '連想ゲーム（お題当て）', '💭', 'desk-group', '室内レク（静かに楽しむ系）', array['中学年', '高学年']::text[], array['雨の日']::text[], '15〜20分', 'お題カードを書く（10分）', '教室', array['教室']::text[], '4〜6人のグループ', 'お題を書いたカード', array['グループで1人が回答者になり、前を向いて座る（お題は見ない）。', 'ほかの人はお題カードを見て、そのものを説明するヒントを1人ずつ順番に出す。ただし、お題の言葉そのものは使えない。', '回答者が当てられたら、グループに得点。', '回答者を交代しながら、何問正解できたかを数える。']::text[], 'ヒントを出す順番を決めておくと、話す子がかたよりません。「1人1ヒントまで」にすると全員が考えます。', 'お題を教科の言葉（都道府県・理科の用語など）にすると、そのまま復習の時間になります。', null, null, 'three-hint-quiz', 47),
  ('wink-killer', 'ウインクキラー', '😉', 'seated-circle', '室内レク（静かに楽しむ系）', array['中学年', '高学年']::text[], array['お楽しみ会', '学期末', '雨の日']::text[], '10〜15分', '机を下げて円をつくる・トランプの用意（5分）', '教室（机を下げて円に）', array['教室']::text[], 'クラス全体（10人〜）', 'トランプ1組（ジョーカー入り）', array['机を下げて円になって座る。トランプを1人1枚ずつ配り、自分だけが見る。ジョーカーを引いた人が「ウインクキラー」、赤のエースを引いた2人が「探偵」になる。', '合図で開始。全員が顔を上げて、ほかの人と目を合わせる。キラーは目が合った人に、まわりに気づかれないようにそっとウインクする。', 'ウインクされた人は、すぐには反応せず、心の中で5秒数えてから「やられた〜」と言って机に伏せる（またはその場に座る）。', '探偵はあやしい人が分かったら「見つけた！」と言い、もう1人の探偵と「せーの」で同時に指をさす。2人の指が同じ人なら探偵の勝ち。ちがえば探偵は交代。3分たっても見つからず、半分の人が倒れたらキラーの勝ち。']::text[], '「殺す」ではなく「やられた」「倒れた」という言い方に統一すると、教室でも扱いやすくなります。倒れた人は声を出さずに見守るのもルールの1つです。', '35人のままだと探偵2人では見つけられず、だらだら長引きます。8〜10人のグループに分け、グループごとにキラー1人・探偵1人を置いて同時に進めてください。探偵を置かず「最後に全員でせーので指さす」だけにすると、低学年でも遊べます。', 'ふざけて本当に倒れ込むとけがにつながるので、「やられた」は机に伏せる・その場に座ることと決めておきます。犯人を当てられなかった人を責めないことも先に確認します。', 'ウインクができない子は、目が合ったときに1回だけうなずく合図にかえてもかまいません。人と目を合わせ続けるのが苦手な子には、時間を計る係やカードを配る係をお願いします。キラーと探偵は毎回くじで引き直し、同じ子が続けて疑われないようにします。', null, 48),
  ('itsu-doko', 'いつどこでゲーム', '📝', 'desk-group', '室内レク（静かに楽しむ系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会', '雨の日']::text[], '20〜30分', 'メモ用紙を1人4枚ずつ配る・袋を4つ用意（5分）', '教室（席のまま）', array['教室']::text[], 'クラス全体', 'メモ用紙（1人4枚）、袋か箱4つ（「いつ」「どこで」「だれが」「なにをした」用）', array['1人4枚の紙を配り、それぞれに「いつ」「どこで」「だれが」「なにをした」を1つずつ書く（1・2年生は「だれが」「なにをした」の2枚だけにする）。', '書いた紙は中が見えないように折って、種類ごとの袋に入れる。', '先生が「いつ→どこで→だれが→なにをした」の順に1枚ずつ引いて、つなげて読み上げる。', '紙がなくなるまで続ける。勝ち負けはなく、おかしな文ができるほど盛り上がる。']::text[], '先生が抑揚をつけて読むと、同じ文でも一気に盛り上がります。国語の「5W1H」の学習ともつなげられます。', '「だれが」を人の名前ではなく「動物」「アニメのキャラクター」に限定すると、だれかをからかう文になりません。低学年は「いつ」「だれが」の2種類だけにすると書きやすいです。', '「自分が言われたら嫌なことは書かない」を、書き始める前に必ず全員で確認します。読み上げる前に先生が紙に目を通しておくと、より安心です。', '書くのがむずかしい子は、先生に言って書いてもらったり、絵でかいたりしてもよいことにします。', null, 49),
  ('epicenter', '震源地ゲーム', '👀', 'gym-circle', '室内レク（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会', '雨の日']::text[], '10〜15分', '机を下げる（5分）', '教室（机を下げて）・多目的室', array['教室']::text[], 'クラス全体', 'なし', array['鬼を1人決め、廊下など輪の中が見えない場所で待ってもらう。', '残りの人で輪を作り、その中の1人を「震源地（しんげんち）」＝みんながまねをするもとの人に決める。', '震源地が手びょうしやポーズを変えると、まわりの人も同じ動きをまねする。震源地は、鬼に気づかれないように少しずつ動きを変える。', '鬼が輪の中に入り、3回まで「震源地は〇〇さん！」と当てる。当てられたら鬼の勝ち、当てられなければ震源地の勝ち。役を交代してくり返す。']::text[], '全員が同じ動きをしているので、震源地はなかなかバレません。「震源地を見つめすぎない」のがまねするときのコツです。', '机を下げられないときは、椅子に座ったままでもできます。', null, null, 'epicenter-game', 50),
  ('human-knot', '人間知恵の輪', '🧶', 'gym-circle', '室内レク（体を動かす系）', array['中学年', '高学年']::text[], array['学級開き', '雨の日']::text[], '10〜15分', '机を下げる（5分）', '教室（机を下げて）・体育館', array['教室', '体育館']::text[], '6〜8人のグループ', 'なし', array['6〜8人で内側を向いて輪になり、両手を前に出す。', '右手で、となりの人ではないだれかの手をにぎる。次に左手で、また別の人の手をにぎる（手がからまった「知恵の輪」の状態になる）。', '手を離さずに、くぐったり、またいだりしながら、1つの輪にほどくことを目指す。', 'ほどけたグループから座る。時間内にほどけなくても、どこまで進んだかを見せ合って終わる。']::text[], '声をかけ合わないとほどけません。「だれが指示を出すか」を決めてから始めると、ぐっと早くほどけます。', '人数を4〜5人にすると簡単になり、中学年でも成功しやすくなります。', '手を強く引っぱらない、痛いときは「痛い」と言ってすぐ手を離してよい、と先に決めます。', '短いタオルやひもを人数分用意し、直接手をにぎるかわりに両端を持って輪を作ると、ふれ合わずに同じ活動ができます。男女が混ざったグループでは、はじめからタオルを使う形にしておくと、輪に入るのをためらう子が減ります。', null, 51),
  ('spoon-relay', 'ピンポン玉運びリレー', '🥄', 'team-line', '室内レク（体を動かす系）', array['低学年', '中学年', '高学年']::text[], array['お楽しみ会', '雨の日']::text[], '15〜20分', 'お玉とピンポン玉をチームの数だけ用意（5分）', '教室（机を下げて）・体育館', array['教室', '体育館']::text[], 'クラス全体（3〜4チーム）', 'お玉（またはスプーン）とピンポン玉を、チームの数だけ', array['チームごとに1列に並び、先頭がお玉にピンポン玉をのせる。', '落とさないように歩いて、決めた場所を回って戻り、次の人に渡す。', '途中で落としたら、その場で拾ってのせ直してから進む。', '全員が運び終わったチームの勝ち。']::text[], '「走らない」ルールにすると、ゆっくり確実に運ぶ子が活躍します。足の速さで差がつかないリレーです。', 'うちわに風船をのせて運ぶ「風船運びリレー」にすると、さらにゆっくりになり低学年でも盛り上がります。', '走ると転びます。「歩くだけ」「落ちた玉を追いかけて走らない」を先に約束します。', null, null, 52),
  ('paper-tower', 'ペーパータワー', '🗼', 'desk-group', '室内レク（静かに楽しむ系）', array['中学年', '高学年']::text[], array['学期末', '雨の日']::text[], '20〜30分', '紙を1グループ20枚ずつ用意（5分）', '教室', array['教室']::text[], '4〜6人のグループ', 'A4用紙（1グループ20枚程度）※はさみ・テープは使わない', array['グループごとに同じ枚数の紙を配る。折る・立てる・重ねるのは自由だが、はさみやテープは使わない。', '2分の作戦タイムのあと、5分間でできるだけ高いタワーを立てる。', '手を離して10秒立っていられたら成功。ものさしで高さをはかる。', '1回目の結果を見て作戦を話し合い、もう一度挑戦する。']::text[], 'ねらいは「1回目より2回目を伸ばす」こと。うまくいったことをグループで言葉にしてから2回目に入ると、話し合いの力が育ちます。', '紙を新聞紙に変えると、中学年でも立てやすくなります。', null, null, null, 53),
  ('three-seconds', '3秒チャレンジ', '⚡', 'quiz', '室内レク（静かに楽しむ系）', array['低学年', '中学年', '高学年']::text[], array['雨の日']::text[], '5〜10分', 'お題を5つほど考える（3分）', '教室（席のまま）', array['教室']::text[], 'クラス全体・グループ', 'なし', array['先生が「赤いもの」「校庭にあるもの」などのお題を出す。', '列（または班）の順番に、1人ずつ3秒以内で答える。答えられたらセーフ。1人1回だけ「パス」が使え、パスはアウトに数えない。', '前の人と同じ答えは言えない。アウトになった人が出たら、次のお題に進む。', 'アウトがいちばん少なかった列（班）の勝ち。']::text[], '3秒という短さがちょうどよい緊張感になります。答えに詰まる子が続いたら、お題をやさしいものに変えて立て直します。', '「英語で言う」「今日の授業に出てきた言葉で」など条件をつけると、そのまま学習の復習になります。', null, 'すぐに言葉が出ない子のために「パス」を先に全員へ知らせておきます。指さして答えたり、となりの子と一緒に答えたりしてもよいことにします。', null, 54),
  ('scavenger-race', '借り物競走', '🎒', 'relay', 'そとあそび・体育館（体を動かす系）', array['中学年', '高学年']::text[], array['お楽しみ会', '学期末']::text[], '20〜30分', 'お題カードを用意する（10分）', '体育館・校庭', array['体育館', '校庭']::text[], 'クラス全体（3〜4チーム）', 'お題を書いたカード、コーン', array['スタート地点から少し離れた所に、お題カードを伏せて置く。', '合図で走り、カードを1枚めくってお題（「白いもの」「文字が書いてあるもの」など）を確かめる。', 'お題に合うものを、コートのそばに置いた「かしだしコーナー」（体育着袋・文具・ボールなどを並べておく）から探して持ち、ゴールして次の人にタッチする。校舎の中へ取りに行くのは禁止にする。', '全員が走り終わったチームの勝ち。借りたものは、終わったら必ず持ち主に返す。']::text[], 'お題は必ず「もの」にします。「めがねの人」のように人を連れてくるお題は、選ばれ方で嫌な思いをする子が出るので使いません。', '教室で行うときは、道具箱やランドセルの中にあるもの限定にすると、短い時間で終わります。', '人の持ち物を勝手に持っていかないよう、「借りるときは必ず持ち主に聞く」をルールにします。探している人とゴールへ走る人がぶつからないよう、通り道を分けておきます。暑い時期は、とちゅうで一度止めて水分をとる時間をつくります。暑さ指数が高い日は、時間を短くするか日かげでできる遊びに変えてください。', null, null, 55),
  ('three-legged', '二人三脚リレー', '👟', 'relay', 'そとあそび・体育館（体を動かす系）', array['中学年', '高学年']::text[], array['お楽しみ会', '学期末']::text[], '15〜20分', 'ひも（タスキ）をペアの数だけ用意（5分）', '校庭・体育館', array['校庭', '体育館']::text[], 'クラス全体（ペア×3〜4チーム）', '足を結ぶひも・タスキ（ペアの数だけ）', array['2人1組になり、となり合った足首を、きつくならないようにひもで結ぶ。', '肩を組み、「いち、に」と声を合わせて歩く練習を1分する。', '合図でスタート。コーンを回って戻り、次のペアにタッチする。', '全ペアが走り終わったチームの勝ち。']::text[], '走るより「速く歩く」ほうが結果的に速くなります。練習の1分を必ずとると、転倒がぐっと減ります。', '不安なペアには距離の短い「歩くだけコース」を用意すると、全員が参加できます。高学年では、ペアは本人たちの希望で組ませ、同性どうしでそろえてよいことを先に伝えておきます。', 'ひもは足首の少し上にゆるめに結び、転んだらすぐほどけるようにします。身長差が大きいペアは組まないようにし、コースの間隔を広くとります。暑い時期は、とちゅうで一度止めて水分をとる時間をつくります。暑さ指数が高い日は、時間を短くするか日かげでできる遊びに変えてください。', null, null, 56),
  ('shotoku-taishi', '聖徳太子ゲーム', '👂', 'desk-group', '室内レク（静かに楽しむ系）', array['中学年', '高学年']::text[], array['お楽しみ会', '雨の日']::text[], '15〜20分', 'お題（3〜5文字の言葉）を10個ほど用意（5分）', '教室', array['教室']::text[], 'クラス全体（3〜5人の出題チーム）', 'お題を書いたカード', array['出題する3〜5人が前に出て、先生からお題の言葉（例：「きゅうしょく」）を見せてもらう。', '出題者は1人1文字ずつ担当を決める（「き」「ゅ」「う」……）。', '「せーの」で全員が同時に、自分の1文字だけを声に出して言う。', '聞いていた人は、何という言葉だったかを当てる。当たったら出題チームを交代する。']::text[], '1回では聞き取れないので、2〜3回言ってあげると盛り上がります。35人学級では出題チームを2〜3組つくって交代で前に立たせると、見ているだけの時間が短くなります。', '人数を増やす（5文字・6文字の言葉にする）と一気に難しくなります。教科書に出てきた言葉をお題にすると復習にもなります。', null, '声を出すのがむずかしい子は、出題チームの「お題をえらぶ係」「せーの、の合図係」として一緒に前に立ちます。', null, 57),
  ('word-wolf', 'ワードウルフ', '🐺', 'desk-group', '室内レク（静かに楽しむ系）', array['高学年']::text[], array['お楽しみ会', '学期末', '雨の日']::text[], '20〜30分', 'お題カードを人数分つくる（10分）', '教室', array['教室']::text[], '4〜8人のグループ', 'お題を書いたカード（1人1枚）', array['グループの人数分のカードを配る。ほとんどの人は同じお題（例：「カレー」）だが、1人だけ少しちがうお題（例：「シチュー」）になっている。自分のカードは自分だけが見る。', '自分が多数派か少数派かは分からないまま、3分間、そのお題について話し合う（「色は？」「いつ食べる？」など）。お題の言葉そのものは言わない。', '話し合いのあと、「せーの」でいちばんあやしい人を指さす。', 'いちばん票が多かった人のカードを見せる。少数派を当てられたら多数派の勝ち、ちがえば少数派の勝ち。']::text[], 'お題は「カレーとシチュー」「えんぴつとシャープペン」のように、近いけれど少しちがうものにすると話し合いが盛り上がります。', '1回戦が終わったら、少数派だった人に「どこでバレたと思う？」と聞くと、話し合いのふり返りになります。', '少数派を探すゲームなので、「見つかっても責めない」「ふだんの関係を持ち込まない」を必ず先に確認します。人の性格・見た目に関わるお題は使いません。ふだんから関係が心配な子がいるクラスでは、別のレクを選んでください。', null, null, 58),
  ('three-color-tag', '三色鬼', '🚦', 'field', 'そとあそび（鬼ごっこ系）', array['中学年', '高学年']::text[], array['お楽しみ会']::text[], '15〜20分', '3色に分けてビブスを配る（初めてなら10分）', '校庭・体育館', array['校庭', '体育館']::text[], 'クラス全体（3チーム）', '3色が分かるもの（ビブス、赤白帽＋たすきなど）', array['3チームに分かれ、色で分かるようにする（赤・青・黄）。コートのすみに、チームごとの陣地（じんち）＝自分たちの場所をつくる。', '「赤は青を追う」「青は黄を追う」「黄は赤を追う」と、追いかける相手が輪になるように決める。追いながら、同時に追われることになる。', 'タッチされた人は、タッチした相手チームの陣地に行ってしゃがんで待つ。味方が来てタッチしてくれたら復活できる。', '3分たったら止めて、しゃがんでいない人がいちばん多いチームの勝ち。追いかける向きを入れかえて、もう一度行う。']::text[], '追いながら追われるので、足の速さだけで決まりません。夢中で追いかけている子を、後ろからそっとタッチできるのがこの遊びの面白さです。', '復活なしにすると短い時間で決着がつきます。体育の準備運動としても使えます。', '自分がだれを追い、だれから逃げるのかを、始める前に色ごとに声に出して確認します。ぶつかりやすいので、範囲は広めにとります。暑い時期は、とちゅうで一度止めて水分をとる時間をつくります。暑さ指数が高い日は、時間を短くするか日かげでできる遊びに変えてください。', null, null, 59),
  ('line-tag', '線おに', '➰', 'field', 'そとあそび（鬼ごっこ系）', array['低学年', '中学年', '高学年']::text[], array[]::text[], '10〜15分', 'ラインの確認（3分）', '体育館（ラインのある場所）・校庭', array['体育館', '校庭']::text[], 'クラス全体', 'なし（体育館のラインをそのまま使う）', array['鬼を2〜3人決める。全員、体育館に引いてある線（ライン）の上しか歩いたり走ったりできない。', '線から足がはみ出したら、その人は鬼と交代する（または1回休み）。', '鬼にタッチされた人も交代する。', '3分ごとに区切り、鬼を入れかえてくり返す。']::text[], '走れる場所が線の上だけなので、スピードより「どこへ逃げるか」の判断で決まります。運動が苦手な子でも勝てる鬼ごっこです。', '線の交わるところを「安全地帯（3秒だけ止まれる）」にすると、低学年でも長く楽しめます。', '線の上ですれちがうときにぶつかりやすいので、「走るのは同じ向き」と決めるか、鬼の人数を少なめにします。', null, null, 60)
) as seed(slug, title, emoji, scene, category, grades, occasions, duration, prep, place, places, group_size, materials, steps, tip, variation, safety, inclusion, icebreaker_slug, sort_order)
where not exists (select 1 from recreations);
